'use client';

import React, { Suspense } from 'react';
import Link from 'next/link';
import { useSearchParams } from 'next/navigation';
import { useStore } from '@/lib/context/StoreContext';
import { ProductCatalogGrid } from '@/components/product/ProductCatalogGrid';

function ShopContent() {
  const searchParams = useSearchParams();
  const { products, categories } = useStore();

  const categorySlug = searchParams.get('category');
  const subcategorySlug = searchParams.get('subcategory');
  const searchQuery = searchParams.get('q');

  const currentCategory = categories.find((c) => c.slug === categorySlug);
  const currentSubcategory = currentCategory?.subcategories?.find((s) => s.slug === subcategorySlug);

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Breadcrumb Navigation */}
      <nav className="flex items-center gap-2 text-xs text-stone-500 dark:text-stone-400 mb-6 font-medium">
        <Link href="/" className="hover:text-stone-900 dark:hover:text-stone-100">
          Home
        </Link>
        <span>/</span>
        <Link href="/shop" className="hover:text-stone-900 dark:hover:text-stone-100">
          Shop
        </Link>
        {currentCategory && (
          <>
            <span>/</span>
            <Link href={`/shop?category=${currentCategory.slug}`} className="hover:text-stone-900 dark:hover:text-stone-100">
              {currentCategory.name}
            </Link>
          </>
        )}
        {currentSubcategory && (
          <>
            <span>/</span>
            <span className="text-[#c46331]">{currentSubcategory.name}</span>
          </>
        )}
      </nav>

      {/* Clean Page Title Header */}
      <div className="mb-8">
        <h1 className="font-serif text-2xl sm:text-4xl font-bold text-stone-900 dark:text-stone-100 tracking-tight">
          {searchQuery
            ? `Results for "${searchQuery}"`
            : currentSubcategory
            ? currentSubcategory.name
            : currentCategory
            ? currentCategory.name
            : 'All Atelier Pieces'}
        </h1>
        <p className="text-xs sm:text-sm text-stone-500 dark:text-stone-400 mt-1.5 max-w-xl">
          {currentCategory?.description || 'Browse our complete catalog of masterfully crafted luxury creations.'}
        </p>
      </div>

      {/* Interactive Catalog Grid */}
      <ProductCatalogGrid
        products={products}
        categories={categories}
        initialCategory={categorySlug || undefined}
        initialQuery={searchQuery || undefined}
      />
    </div>
  );
}

export default function ShopPage() {
  return (
    <Suspense fallback={<div className="max-w-7xl mx-auto p-12 text-center text-xs text-stone-500">Loading collection...</div>}>
      <ShopContent />
    </Suspense>
  );
}

'use client';

import React, { useState, useEffect, Suspense } from 'react';
import Link from 'next/link';
import { useSearchParams } from 'next/navigation';
import { DataStore } from '@/lib/store/data-store';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { useCurrency } from '@/lib/context/CurrencyLanguageContext';
import { Order, OrderStatus } from '@/types';
import { formatDateTime, formatDate } from '@/lib/utils';
import {
  Search,
  Truck,
  CheckCircle2,
  Clock,
  Package,
  Home,
  XCircle,
  AlertCircle,
  ExternalLink,
  MapPin,
  ShieldCheck,
  ArrowRight,
  Sparkles,
} from 'lucide-react';
import Image from 'next/image';

function TrackOrderContent() {
  const searchParams = useSearchParams();
  const { formatAmount } = useCurrency();

  const [orderNumberInput, setOrderNumberInput] = useState(searchParams.get('orderNumber') || searchParams.get('id') || '');
  const [contactInput, setContactInput] = useState(searchParams.get('email') || searchParams.get('phone') || '');
  const [order, setOrder] = useState<Order | null>(null);
  const [searched, setSearched] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [attempts, setAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);

  // Auto-search if parameters are provided in URL
  useEffect(() => {
    const qOrder = searchParams.get('orderNumber') || searchParams.get('id');
    const qContact = searchParams.get('email') || searchParams.get('phone');
    if (qOrder && qContact) {
      handleLookup(qOrder, qContact);
    }
  }, [searchParams]);

  const handleLookup = async (ordNum: string, contact: string) => {
    // Check rate limit lockout
    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remainingSecs = Math.ceil((lockoutUntil - Date.now()) / 1000);
      setErrorMsg(`Too many failed lookup attempts. Please wait ${remainingSecs}s before trying again.`);
      return;
    }

    const cleanOrdNum = ordNum.trim().toUpperCase();
    const cleanContact = contact.trim().toLowerCase();

    if (!cleanOrdNum || !cleanContact) {
      setErrorMsg('Please enter both your Order Number and the Email or Phone Number used during checkout.');
      return;
    }

    setErrorMsg('');
    setSearched(true);

    const allOrders = DataStore.getOrders();
    let found = allOrders.find((o) => {
      const matchNumber = o.order_number.toUpperCase() === cleanOrdNum || o.id.toUpperCase() === cleanOrdNum;
      if (!matchNumber) return false;

      const emailMatch = o.guest_email?.toLowerCase() === cleanContact || o.shipping_address?.full_name?.toLowerCase() === cleanContact;
      const phoneMatch = o.guest_phone?.replace(/[^0-9]/g, '') === cleanContact.replace(/[^0-9]/g, '') ||
                         o.shipping_address?.phone?.replace(/[^0-9]/g, '') === cleanContact.replace(/[^0-9]/g, '');

      return emailMatch || phoneMatch;
    });

    // Fallback to Supabase database if not in local store
    if (!found && isSupabaseConfigured) {
      try {
        const { data: dbOrder } = await supabase
          .from('orders')
          .select('*')
          .or(`order_number.ilike.${cleanOrdNum},id.eq.${cleanOrdNum}`)
          .single();

        if (dbOrder) {
          const emailMatch = dbOrder.guest_email?.toLowerCase() === cleanContact || dbOrder.shipping_address?.full_name?.toLowerCase() === cleanContact;
          const phoneMatch = dbOrder.guest_phone?.replace(/[^0-9]/g, '') === cleanContact.replace(/[^0-9]/g, '') ||
                             dbOrder.shipping_address?.phone?.replace(/[^0-9]/g, '') === cleanContact.replace(/[^0-9]/g, '');

          if (emailMatch || phoneMatch) {
            const { data: dbItems } = await supabase.from('order_items').select('*').eq('order_id', dbOrder.id);
            const { data: dbHistory } = await supabase.from('order_status_history').select('*').eq('order_id', dbOrder.id).order('created_at', { ascending: true });

            found = {
              ...dbOrder,
              items: dbItems || [],
              status_history: dbHistory || [],
            };
          }
        }
      } catch (err) {
        console.error('Supabase track order error:', err);
      }
    }

    if (found) {
      setOrder(found);
      setAttempts(0);
    } else {
      setOrder(null);
      const newAttempts = attempts + 1;
      setAttempts(newAttempts);
      if (newAttempts >= 5) {
        setLockoutUntil(Date.now() + 120000); // 2 min cooldown
        setErrorMsg('Too many invalid lookup attempts. Please wait 2 minutes or contact concierge support.');
      } else {
        setErrorMsg(`No matching order found for ${cleanOrdNum} with the provided contact info. Please verify your order number and email/phone.`);
      }
    }
  };

  const statusOrder: OrderStatus[] = ['pending', 'confirmed', 'shipped', 'out_for_delivery', 'delivered'];
  const isCancelled = order?.status === 'cancelled' || order?.status === 'returned';
  const currentIndex = order && !isCancelled ? statusOrder.indexOf(order.status) : -1;

  const getStatusStepIcon = (status: OrderStatus, index: number) => {
    if (isCancelled) {
      if (status === 'pending') return <CheckCircle2 className="w-5 h-5 text-stone-400" />;
      return <XCircle className="w-5 h-5 text-rose-500" />;
    }
    if (index < currentIndex) return <CheckCircle2 className="w-5 h-5 text-emerald-600" />;
    if (index === currentIndex) {
      switch (status) {
        case 'pending': return <Clock className="w-5 h-5 text-amber-500 animate-pulse" />;
        case 'confirmed': return <CheckCircle2 className="w-5 h-5 text-blue-500 animate-pulse" />;
        case 'shipped': return <Package className="w-5 h-5 text-indigo-500 animate-pulse" />;
        case 'out_for_delivery': return <Truck className="w-5 h-5 text-[#c46331] animate-pulse" />;
        case 'delivered': return <Home className="w-5 h-5 text-emerald-600" />;
      }
    }
    return <div className="w-3 h-3 rounded-full bg-stone-300" />;
  };

  const getStatusLabel = (status: OrderStatus) => {
    switch (status) {
      case 'pending': return 'Order Placed';
      case 'confirmed': return 'Confirmed';
      case 'shipped': return 'Shipped';
      case 'out_for_delivery': return 'Out for Delivery';
      case 'delivered': return 'Delivered';
      default: return status;
    }
  };

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-12 md:py-16">
      {/* Header Banner */}
      <div className="text-center max-w-2xl mx-auto mb-10">
        <div className="w-12 h-12 rounded-full bg-[#c46331]/10 text-[#c46331] flex items-center justify-center mx-auto mb-3">
          <Truck className="w-6 h-6" />
        </div>
        <h1 className="font-serif text-3xl md:text-4xl font-bold text-stone-900 dark:text-stone-100 mb-2">
          Track Your Atelier Order
        </h1>
        <p className="text-xs sm:text-sm text-stone-500 dark:text-stone-400">
          Enter your Order Number and Email or Phone Number to view live status, courier milestones, and delivery estimates. No login required.
        </p>
      </div>

      {/* Lookup Form */}
      <div className="max-w-2xl mx-auto bg-white dark:bg-[#16171b] border border-stone-200 dark:border-stone-800 rounded-3xl p-6 sm:p-8 shadow-sm mb-12">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            handleLookup(orderNumberInput, contactInput);
          }}
          className="space-y-4"
        >
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300 uppercase tracking-wider mb-1.5">
                Order Number *
              </label>
              <input
                type="text"
                required
                placeholder="e.g. OZ-2026-2744"
                value={orderNumberInput}
                onChange={(e) => setOrderNumberInput(e.target.value)}
                className="w-full px-4 py-2.5 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-xs text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331] font-mono transition-all"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300 uppercase tracking-wider mb-1.5">
                Email or Phone *
              </label>
              <input
                type="text"
                required
                placeholder="e.g. patron@example.com"
                value={contactInput}
                onChange={(e) => setContactInput(e.target.value)}
                className="w-full px-4 py-2.5 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-xs text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331] transition-all"
              />
            </div>
          </div>

          {errorMsg && (
            <div className="p-3 bg-red-50 dark:bg-red-950/40 text-red-700 dark:text-red-300 text-xs rounded-xl flex items-center gap-2 border border-red-200 dark:border-red-900/60">
              <AlertCircle className="w-4 h-4 shrink-0" />
              <span>{errorMsg}</span>
            </div>
          )}

          <button
            type="submit"
            className="w-full py-3 bg-[#1a1714] hover:bg-[#c46331] text-white text-xs font-bold uppercase tracking-widest rounded-xl transition-all shadow-sm flex items-center justify-center gap-2 cursor-pointer"
          >
            <Search className="w-4 h-4" />
            <span>Track Shipment Status</span>
          </button>
        </form>
      </div>

      {/* Verified Order Results */}
      {order && (
        <div className="space-y-8 animate-fade-in-up">
          {/* Order Overview Header Card */}
          <div className="bg-white dark:bg-[#16171b] border border-stone-200 dark:border-stone-800 rounded-3xl p-6 sm:p-8 shadow-sm">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 pb-6 border-b border-stone-100 dark:border-stone-800">
              <div>
                <span className="text-[11px] font-bold uppercase tracking-wider text-[#c46331] dark:text-amber-400 bg-amber-100 dark:bg-amber-950/60 px-2.5 py-1 rounded-full">
                  Status: {order.status.replace(/_/g, ' ').toUpperCase()}
                </span>
                <h2 className="text-2xl font-serif font-bold text-stone-900 dark:text-stone-100 mt-2">
                  Order #{order.order_number}
                </h2>
                <p className="text-xs text-stone-500 dark:text-stone-400 mt-0.5">
                  Placed on {formatDate(order.created_at)} • {order.items.length} item(s) • Total: {formatAmount(order.total_amount)}
                </p>
              </div>

              {order.tracking_number && (
                <div className="text-left sm:text-right bg-stone-50 dark:bg-stone-900 p-3 rounded-xl border border-stone-200 dark:border-stone-800">
                  <p className="text-xs font-semibold text-stone-800 dark:text-stone-200">
                    Courier: {order.tracking_courier || 'Express Dispatch'}
                  </p>
                  <p className="text-xs font-mono text-stone-500 dark:text-stone-400 mt-0.5">
                    AWB: {order.tracking_number}
                  </p>
                  {order.tracking_url && (
                    <a
                      href={order.tracking_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 text-xs text-[#c46331] dark:text-amber-400 font-semibold mt-1 hover:underline"
                    >
                      Live Courier Tracking <ExternalLink className="w-3 h-3" />
                    </a>
                  )}
                </div>
              )}
            </div>

            {/* Stepper Timeline */}
            {!isCancelled ? (
              <div className="pt-8 pb-4">
                <div className="relative">
                  <div className="absolute left-0 top-1/2 -mt-0.5 w-full h-1 bg-stone-100 dark:bg-stone-800 -z-0" />
                  <div className="relative flex justify-between z-10">
                    {statusOrder.map((step, idx) => {
                      const isCompleted = currentIndex >= idx;
                      const isCurrent = currentIndex === idx;
                      return (
                        <div key={step} className="flex flex-col items-center">
                          <div
                            className={`w-10 h-10 rounded-full flex items-center justify-center bg-white dark:bg-[#16171b] border-2 transition-all ${
                              isCompleted
                                ? 'border-emerald-600 dark:border-emerald-500 bg-emerald-50 dark:bg-emerald-950/60 text-emerald-600 dark:text-emerald-400 shadow-sm'
                                : 'border-stone-200 dark:border-stone-700 text-stone-300 dark:text-stone-600'
                            }`}
                          >
                            {getStatusStepIcon(step, idx)}
                          </div>
                          <span
                            className={`mt-2 text-xs font-medium text-center ${
                              isCurrent
                                ? 'text-[#c46331] dark:text-amber-400 font-bold'
                                : isCompleted
                                ? 'text-stone-800 dark:text-stone-200 font-semibold'
                                : 'text-stone-400 dark:text-stone-500'
                            }`}
                          >
                            {getStatusLabel(step)}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            ) : (
              <div className="py-6 text-center text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/40 rounded-xl my-4 text-xs font-medium border border-rose-200 dark:border-rose-900/60">
                This order has been {order.status}.
              </div>
            )}
          </div>

          {/* Grid: Items & Shipping details */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Left 2 Cols: Items List */}
            <div className="lg:col-span-2 bg-white dark:bg-[#16171b] border border-stone-200 dark:border-stone-800 rounded-3xl p-6 shadow-sm">
              <h3 className="font-serif font-bold text-stone-900 dark:text-stone-100 text-base mb-4">
                Items in this Shipment
              </h3>
              <div className="divide-y divide-stone-100 dark:divide-stone-800">
                {order.items.map((item) => (
                  <div key={item.id} className="py-3.5 flex items-center justify-between gap-4">
                    <div className="flex items-center gap-3">
                      <div className="w-14 h-14 rounded-xl bg-stone-100 dark:bg-stone-800 overflow-hidden shrink-0 border border-stone-200 dark:border-stone-700">
                        {item.product_image && (
                          <img
                            src={item.product_image}
                            alt={item.product_title}
                            className="w-full h-full object-cover"
                          />
                        )}
                      </div>
                      <div>
                        <h4 className="text-xs font-semibold text-stone-900 dark:text-stone-100">{item.product_title}</h4>
                        {item.variant_details && (
                          <p className="text-[11px] text-stone-500 dark:text-stone-400">
                            {item.variant_details.size && `Size: ${item.variant_details.size}`}
                            {item.variant_details.color && ` • Color: ${item.variant_details.color}`}
                          </p>
                        )}
                        <p className="text-xs text-stone-500 dark:text-stone-400 mt-0.5">Qty: {item.quantity}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-xs font-bold text-stone-900 dark:text-stone-100">{formatAmount(item.total_price)}</p>
                      <p className="text-[10px] text-stone-400 dark:text-stone-500">{formatAmount(item.unit_price)} each</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Right Col: Address */}
            <div className="space-y-6">
              <div className="bg-white dark:bg-[#16171b] border border-stone-200 dark:border-stone-800 rounded-3xl p-6 shadow-sm">
                <h3 className="font-serif font-bold text-stone-900 dark:text-stone-100 text-base mb-3 flex items-center gap-2">
                  <MapPin className="w-4 h-4 text-[#c46331]" /> Delivery Address
                </h3>
                <div className="text-xs text-stone-600 dark:text-stone-300 space-y-1">
                  <p className="font-semibold text-stone-900 dark:text-stone-100">{order.shipping_address.full_name}</p>
                  <p>{order.shipping_address.street}</p>
                  {order.shipping_address.apartment && <p>{order.shipping_address.apartment}</p>}
                  <p>
                    {order.shipping_address.city}, {order.shipping_address.state} {order.shipping_address.postal_code}
                  </p>
                  <p>{order.shipping_address.country}</p>
                  <p className="pt-2 font-mono text-stone-500 dark:text-stone-400">Ph: {order.shipping_address.phone}</p>
                </div>
              </div>

              {/* Guest Upsell Prompt */}
              {(!order.user_id || order.guest_email) && (
                <div className="bg-gradient-to-br from-stone-900 to-stone-800 text-white rounded-3xl p-6 shadow-sm">
                  <div className="flex items-center gap-2 text-amber-400 text-xs font-bold uppercase tracking-wider mb-2">
                    <Sparkles className="w-4 h-4" /> Save Order to Account
                  </div>
                  <p className="text-xs text-stone-300 mb-4 leading-relaxed">
                    Create a free Ozeira Patron account to save this order to your permanent dashboard and claim <strong>250 Welcome Points</strong>.
                  </p>
                  <Link
                    href={`/auth/signup?email=${encodeURIComponent(order.guest_email || '')}`}
                    className="block w-full text-center py-2.5 bg-[#c46331] hover:bg-[#b05325] text-white text-xs font-bold uppercase tracking-wider rounded-xl transition-colors"
                  >
                    Create Account in 1-Click →
                  </Link>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default function TrackOrderPage() {
  return (
    <Suspense fallback={<div className="p-12 text-center text-xs text-stone-500">Loading Order Tracker...</div>}>
      <TrackOrderContent />
    </Suspense>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { DataStore } from '@/lib/store/data-store';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { useCurrency } from '@/lib/context/CurrencyLanguageContext';
import { Download, TrendingUp, ShoppingBag, CreditCard, Users, BarChart3 } from 'lucide-react';
import type { Order, Product, UserProfile } from '@/types';

export default function AnalyticsAdminPage() {
  const { formatAmount: formatPrice } = useCurrency();
  const [orders, setOrders] = useState<Order[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [users, setUsers] = useState<UserProfile[]>([]);

  useEffect(() => {
    async function loadData() {
      let currentOrders = DataStore.getOrders();
      setProducts(DataStore.getProducts());
      setUsers(DataStore.getUsers());

      if (isSupabaseConfigured) {
        try {
          const { data: dbOrders } = await supabase.from('orders').select('*').order('created_at', { ascending: false });
          if (dbOrders && dbOrders.length > 0) {
            const { data: dbItems } = await supabase.from('order_items').select('*');
            const itemsMap = new Map<string, any[]>();
            (dbItems || []).forEach(item => {
              const list = itemsMap.get(item.order_id) || [];
              list.push(item);
              itemsMap.set(item.order_id, list);
            });

            currentOrders = dbOrders.map(o => ({
              ...o,
              items: itemsMap.get(o.id) || o.items || [],
              status_history: o.status_history || [],
            }));
          }
        } catch (err) {
          console.error('Analytics Supabase sync error:', err);
        }
      }

      setOrders(currentOrders);
    }

    loadData();
  }, []);

  const validOrders = orders.filter(o => o.status !== 'cancelled' && o.status !== 'returned');
  const totalRevenue = validOrders.reduce((sum, o) => sum + (o.total_amount || 0), 0);
  const totalOrders = orders.length;
  const aov = totalOrders > 0 ? totalRevenue / totalOrders : 0;
  const totalCustomers = users.length;
  const totalProducts = products.length;

  const categoryRev: Record<string, number> = {};
  validOrders.forEach(o => {
    (o.items || []).forEach(i => {
      const p = products.find(prod => prod.id === i.product_id);
      if (p) {
        categoryRev[p.category_id] = (categoryRev[p.category_id] || 0) + (i.total_price || 0);
      }
    });
  });
  const topCategories = Object.entries(categoryRev).sort((a,b) => b[1]-a[1]).slice(0, 5);

  const prodSales: Record<string, number> = {};
  validOrders.forEach(o => (o.items || []).forEach(i => prodSales[i.product_id] = (prodSales[i.product_id] || 0) + (i.quantity || 0)));
  const topProducts = Object.entries(prodSales).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([id, qty]) => {
    return { product: products.find(p=>p.id===id), qty };
  });

  const razorpay = validOrders.filter(o => o.payment_method === 'razorpay').length;
  const cod = validOrders.filter(o => o.payment_method === 'cod').length;
  const razorpayPercent = totalOrders ? Math.round((razorpay/totalOrders)*100) : 0;
  const codPercent = totalOrders ? Math.round((cod/totalOrders)*100) : 0;

  const statusCounts = orders.reduce((acc, o) => { acc[o.status] = (acc[o.status] || 0) + 1; return acc; }, {} as Record<string,number>);

  const handleExport = () => {
    const csv = ['Date,Order,Total,Status'].concat(
      orders.map(o => `${o.created_at},${o.order_number},${o.total_amount},${o.status}`)
    ).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'ozeira_sales_report.csv';
    a.click();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-neutral-900 dark:text-neutral-100">Atelier Performance & Intelligence</h1>
          <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-1">Real-time GMV, unit velocity, average basket value, and payment mix.</p>
        </div>
        <button onClick={handleExport} className="bg-white dark:bg-[#14151a] border border-neutral-200 dark:border-neutral-800 text-xs font-semibold text-neutral-700 dark:text-neutral-300 px-4 py-2 rounded-xl flex items-center gap-2 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors shadow-sm">
          <Download className="w-3.5 h-3.5" /> Export Revenue CSV
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <p className="text-neutral-500 dark:text-neutral-400 text-xs mb-1 flex items-center gap-1.5 font-medium"><TrendingUp className="w-3.5 h-3.5 text-emerald-500"/> Total GMV</p>
          <p className="text-xl font-bold text-neutral-900 dark:text-neutral-100">{formatPrice(totalRevenue)}</p>
        </div>
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <p className="text-neutral-500 dark:text-neutral-400 text-xs mb-1 flex items-center gap-1.5 font-medium"><ShoppingBag className="w-3.5 h-3.5 text-blue-500"/> Total Orders</p>
          <p className="text-xl font-bold text-neutral-900 dark:text-neutral-100">{totalOrders}</p>
        </div>
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <p className="text-neutral-500 dark:text-neutral-400 text-xs mb-1 flex items-center gap-1.5 font-medium"><BarChart3 className="w-3.5 h-3.5 text-purple-500"/> Basket AOV</p>
          <p className="text-xl font-bold text-neutral-900 dark:text-neutral-100">{formatPrice(aov)}</p>
        </div>
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <p className="text-neutral-500 dark:text-neutral-400 text-xs mb-1 flex items-center gap-1.5 font-medium"><Users className="w-3.5 h-3.5 text-brand-amber"/> Total Patrons</p>
          <p className="text-xl font-bold text-neutral-900 dark:text-neutral-100">{totalCustomers} <span className="text-emerald-500 text-xs font-normal ml-1">↑ Active</span></p>
        </div>
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <p className="text-neutral-500 dark:text-neutral-400 text-xs mb-1 flex items-center gap-1.5 font-medium"><CreditCard className="w-3.5 h-3.5 text-neutral-500"/> Catalog Pieces</p>
          <p className="text-xl font-bold text-neutral-900 dark:text-neutral-100">{totalProducts}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-[#14151a] p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <h2 className="text-base font-bold text-neutral-900 dark:text-neutral-100 mb-4">Top Velocity Pieces</h2>
          <div className="space-y-4">
            {topProducts.map((p, i) => (
              <div key={i} className="flex justify-between items-center text-xs">
                <span className="flex-1 truncate pr-4 font-medium text-neutral-800 dark:text-neutral-200">{p.product?.title || 'Bespoke Atelier Piece'}</span>
                <span className="font-semibold bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-neutral-100 px-2.5 py-1 rounded-lg">{p.qty} ordered</span>
              </div>
            ))}
            {topProducts.length === 0 && <p className="text-xs text-neutral-400">No orders yet.</p>}
          </div>
        </div>

        <div className="bg-white dark:bg-[#14151a] p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <h2 className="text-base font-bold text-neutral-900 dark:text-neutral-100 mb-4">Revenue Contribution by Category</h2>
          <div className="space-y-4 text-xs">
            {topCategories.map(([catId, rev], i) => {
              const max = Math.max(...topCategories.map(c=>c[1])) || 1;
              const pct = Math.round((rev / max) * 100);
              const catObj = DataStore.getCategories().find(c => c.id === catId || c.slug === catId);
              const catName = catObj?.name || catId.replace(/-/g, ' ');
              return (
                <div key={i}>
                  <div className="flex justify-between mb-1.5">
                    <span className="font-medium text-neutral-800 dark:text-neutral-200">{catName}</span>
                    <span className="font-bold text-neutral-900 dark:text-neutral-100">{formatPrice(rev)}</span>
                  </div>
                  <div className="w-full bg-neutral-100 dark:bg-neutral-800 rounded-full h-2 overflow-hidden">
                    <div className="bg-brand-amber h-2 rounded-full" style={{ width: `${pct}%` }}></div>
                  </div>
                </div>
              )
            })}
            {topCategories.length === 0 && <p className="text-xs text-neutral-400">No category sales recorded yet.</p>}
          </div>
        </div>

        <div className="bg-white dark:bg-[#14151a] p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <h2 className="text-base font-bold text-neutral-900 dark:text-neutral-100 mb-4">Fulfillment Status Breakdown</h2>
          <div className="space-y-3">
            {Object.entries(statusCounts).map(([status, count]) => {
              const pct = totalOrders ? Math.round((count / totalOrders) * 100) : 0;
              return (
                <div key={status} className="flex items-center gap-3 text-xs">
                  <div className="w-28 capitalize font-medium text-neutral-700 dark:text-neutral-300">{status.replace(/_/g, ' ')}</div>
                  <div className="flex-1 bg-neutral-100 dark:bg-neutral-800 rounded-full h-2.5 overflow-hidden">
                    <div className="bg-brand-amber h-2.5 rounded-full" style={{ width: `${pct}%` }}></div>
                  </div>
                  <div className="w-12 text-right font-bold text-neutral-900 dark:text-neutral-100">{count}</div>
                </div>
              )
            })}
            {Object.keys(statusCounts).length === 0 && <p className="text-xs text-neutral-400">No orders placed yet.</p>}
          </div>
        </div>

        <div className="bg-white dark:bg-[#14151a] p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <h2 className="text-base font-bold text-neutral-900 dark:text-neutral-100 mb-4">Payment Method Distribution</h2>
          <div className="flex items-center justify-center gap-8 py-6">
            <div className="text-center">
              <div className="text-3xl font-extrabold text-blue-600 dark:text-blue-400 mb-1">{razorpayPercent}%</div>
              <p className="text-xs font-semibold text-neutral-700 dark:text-neutral-300">Razorpay Prepaid</p>
              <p className="text-[11px] text-neutral-400">({razorpay} orders)</p>
            </div>
            <div className="h-16 w-px bg-neutral-200 dark:border-neutral-800"></div>
            <div className="text-center">
              <div className="text-3xl font-extrabold text-brand-amber mb-1">{codPercent}%</div>
              <p className="text-xs font-semibold text-neutral-700 dark:text-neutral-300">Cash on Delivery</p>
              <p className="text-[11px] text-neutral-400">({cod} orders)</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { DataStore } from '@/lib/store/data-store';
import { HeroBanner, PromoBanner, Announcement } from '@/types';
import { useStore } from '@/lib/context/StoreContext';
import { cn } from '@/lib/utils';
import { Plus, Edit, Trash2, X, ArrowUp, ArrowDown, Eye } from 'lucide-react';
import Image from 'next/image';
import { ImageUploadDropzone } from '@/components/common/ImageUploadDropzone';

export default function BannersPage() {
  const { refreshData } = useStore();
  const [activeTab, setActiveTab] = useState<'hero' | 'promo' | 'announcement'>('hero');

  const [heroBanners, setHeroBanners] = useState<HeroBanner[]>([]);
  const [promoBanners, setPromoBanners] = useState<PromoBanner[]>([]);
  const [announcement, setAnnouncement] = useState<Announcement | null>(null);

  // Modals state
  const [isHeroModalOpen, setIsHeroModalOpen] = useState(false);
  const [isPromoModalOpen, setIsPromoModalOpen] = useState(false);

  const [heroForm, setHeroForm] = useState<Partial<HeroBanner>>({});
  const [promoForm, setPromoForm] = useState<Partial<PromoBanner>>({});

  const loadData = () => {
    setHeroBanners([...DataStore.getHeroBanners()].sort((a, b) => a.sort_order - b.sort_order));
    setPromoBanners([...DataStore.getPromoBanners()].sort((a, b) => a.sort_order - b.sort_order));
    setAnnouncement(DataStore.getAnnouncement());
  };

  useEffect(() => {
    loadData();
  }, []);

  // --- Hero Banners ---
  const openHeroModal = (banner?: HeroBanner) => {
    if (banner) {
      setHeroForm(banner);
    } else {
      setHeroForm({
        title: '', subtitle: '', button_text: '', button_url: '',
        image_url: '', background_color: '#000000', sort_order: heroBanners.length, is_active: true
      });
    }
    setIsHeroModalOpen(true);
  };

  const saveHeroBanner = (e: React.FormEvent) => {
    e.preventDefault();
    const newBanner = {
      id: heroForm.id || `hero-${Date.now()}`,
      title: heroForm.title || '',
      subtitle: heroForm.subtitle || '',
      button_text: heroForm.button_text || '',
      button_url: heroForm.button_url || '',
      image_url: heroForm.image_url || '',
      background_color: heroForm.background_color || '#000000',
      badge_text: heroForm.badge_text,
      sort_order: heroForm.sort_order || 0,
      is_active: heroForm.is_active ?? true,
      start_date: heroForm.start_date,
      end_date: heroForm.end_date,
    } as HeroBanner;

    let updated = [...heroBanners];
    const idx = updated.findIndex(b => b.id === newBanner.id);
    if (idx >= 0) updated[idx] = newBanner;
    else updated.push(newBanner);

    updated.sort((a, b) => a.sort_order - b.sort_order);
    DataStore.saveHeroBanners(updated);
    setHeroBanners(updated);
    refreshData();
    setIsHeroModalOpen(false);
  };

  const deleteHeroBanner = (id: string) => {
    if (window.confirm('Delete this banner?')) {
      const updated = heroBanners.filter(b => b.id !== id);
      DataStore.saveHeroBanners(updated);
      setHeroBanners(updated);
      refreshData();
    }
  };

  const moveHero = (idx: number, dir: 'up' | 'down') => {
    if (dir === 'up' && idx === 0) return;
    if (dir === 'down' && idx === heroBanners.length - 1) return;
    const target = dir === 'up' ? idx - 1 : idx + 1;
    const updated = [...heroBanners];
    const temp = updated[idx].sort_order;
    updated[idx].sort_order = updated[target].sort_order;
    updated[target].sort_order = temp;
    updated.sort((a, b) => a.sort_order - b.sort_order);
    DataStore.saveHeroBanners(updated);
    setHeroBanners(updated);
    refreshData();
  };

  // --- Promo Banners ---
  const openPromoModal = (banner?: PromoBanner) => {
    if (banner) {
      setPromoForm(banner);
    } else {
      setPromoForm({
        title: '', subtitle: '', link_url: '', image_url: '',
        grid_type: 'half', sort_order: promoBanners.length, is_active: true
      });
    }
    setIsPromoModalOpen(true);
  };

  const savePromoBanner = (e: React.FormEvent) => {
    e.preventDefault();
    const newBanner = {
      id: promoForm.id || `promo-${Date.now()}`,
      title: promoForm.title || '',
      subtitle: promoForm.subtitle || '',
      image_url: promoForm.image_url || '',
      link_url: promoForm.link_url || '',
      grid_type: promoForm.grid_type || 'half',
      badge_text: promoForm.badge_text,
      sort_order: promoForm.sort_order || 0,
      is_active: promoForm.is_active ?? true,
    } as PromoBanner;

    let updated = [...promoBanners];
    const idx = updated.findIndex(b => b.id === newBanner.id);
    if (idx >= 0) updated[idx] = newBanner;
    else updated.push(newBanner);

    updated.sort((a, b) => a.sort_order - b.sort_order);
    DataStore.savePromoBanners(updated);
    setPromoBanners(updated);
    refreshData();
    setIsPromoModalOpen(false);
  };

  const deletePromoBanner = (id: string) => {
    if (window.confirm('Delete this promotional block?')) {
      const updated = promoBanners.filter(b => b.id !== id);
      DataStore.savePromoBanners(updated);
      setPromoBanners(updated);
      refreshData();
    }
  };

  const movePromo = (idx: number, dir: 'up' | 'down') => {
    if (dir === 'up' && idx === 0) return;
    if (dir === 'down' && idx === promoBanners.length - 1) return;
    const target = dir === 'up' ? idx - 1 : idx + 1;
    const updated = [...promoBanners];
    const temp = updated[idx].sort_order;
    updated[idx].sort_order = updated[target].sort_order;
    updated[target].sort_order = temp;
    updated.sort((a, b) => a.sort_order - b.sort_order);
    DataStore.savePromoBanners(updated);
    setPromoBanners(updated);
    refreshData();
  };

  // --- Announcement ---
  const saveAnnouncement = (e: React.FormEvent) => {
    e.preventDefault();
    if (!announcement) return;
    DataStore.saveAnnouncement(announcement);
    refreshData();
    alert('Announcement settings saved successfully.');
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-neutral-900 dark:text-neutral-100">Banners & Promotions</h1>
          <p className="text-sm text-neutral-500 dark:text-neutral-400">Manage hero slider carousels, promo tiles, and marquee bars.</p>
        </div>
        {activeTab !== 'announcement' && (
          <button
            onClick={() => (activeTab === 'hero' ? openHeroModal() : openPromoModal())}
            className="inline-flex items-center justify-center px-4 py-2 bg-brand-amber hover:bg-brand-amber-dark text-white rounded-lg text-sm font-medium transition-colors"
          >
            <Plus className="w-4 h-4 mr-2" />
            {activeTab === 'hero' ? 'Add Hero Slide' : 'Add Promo Tile'}
          </button>
        )}
      </div>

      {/* Tabs */}
      <div className="flex space-x-1 border-b border-neutral-200 dark:border-neutral-800">
        {(['hero', 'promo', 'announcement'] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={cn(
              "px-4 py-2.5 text-sm font-medium transition-colors relative",
              activeTab === tab 
                ? "text-brand-amber font-semibold" 
                : "text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-neutral-100"
            )}
          >
            {tab === 'hero' ? 'Hero Banners' : tab === 'promo' ? 'Promo Banners' : 'Announcement Bar'}
            {activeTab === tab && (
              <span className="absolute bottom-0 left-0 w-full h-0.5 bg-brand-amber" />
            )}
          </button>
        ))}
      </div>

      {/* HERO BANNERS */}
      {activeTab === 'hero' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {heroBanners.map((banner, idx) => (
            <div key={banner.id} className="bg-white dark:bg-[#14151a] border border-neutral-200 dark:border-neutral-800 rounded-xl overflow-hidden shadow-sm">
              <div className="relative h-48 w-full bg-neutral-100 dark:bg-neutral-800" style={{ backgroundColor: banner.background_color }}>
                {banner.image_url && (
                  <Image src={banner.image_url} alt={banner.title} fill className="object-cover" />
                )}
                {!banner.is_active && (
                  <div className="absolute top-2 left-2 bg-black/70 text-white text-xs px-2 py-1 uppercase rounded">Inactive</div>
                )}
              </div>
              <div className="p-4">
                <div className="flex justify-between items-start">
                  <h3 className="font-semibold text-base text-neutral-900 dark:text-neutral-100 truncate pr-2">{banner.title}</h3>
                  <div className="flex space-x-1 shrink-0">
                    <button onClick={() => moveHero(idx, 'up')} disabled={idx === 0} className="p-1 text-neutral-400 hover:text-brand-amber disabled:opacity-30"><ArrowUp className="w-4 h-4" /></button>
                    <button onClick={() => moveHero(idx, 'down')} disabled={idx === heroBanners.length - 1} className="p-1 text-neutral-400 hover:text-brand-amber disabled:opacity-30"><ArrowDown className="w-4 h-4" /></button>
                  </div>
                </div>
                <p className="text-xs text-neutral-500 dark:text-neutral-400 line-clamp-1 mb-4">{banner.subtitle}</p>
                <div className="flex justify-between items-center pt-3 border-t border-neutral-100 dark:border-neutral-800">
                  <span className="text-xs font-mono text-neutral-400">Order: {banner.sort_order}</span>
                  <div className="flex space-x-3">
                    <button onClick={() => openHeroModal(banner)} className="text-neutral-500 dark:text-neutral-400 hover:text-brand-amber dark:hover:text-brand-amber text-xs font-medium flex items-center"><Edit className="w-3.5 h-3.5 mr-1" /> Edit</button>
                    <button onClick={() => deleteHeroBanner(banner.id)} className="text-red-500 hover:text-red-700 text-xs font-medium flex items-center"><Trash2 className="w-3.5 h-3.5 mr-1" /> Delete</button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* PROMO BANNERS */}
      {activeTab === 'promo' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {promoBanners.map((banner, idx) => (
            <div key={banner.id} className="bg-white dark:bg-[#14151a] border border-neutral-200 dark:border-neutral-800 rounded-xl overflow-hidden shadow-sm">
              <div className="relative h-40 w-full bg-neutral-100 dark:bg-neutral-800">
                {banner.image_url && <Image src={banner.image_url} alt={banner.title} fill className="object-cover" />}
                <div className="absolute bottom-2 right-2 bg-white/90 dark:bg-black/90 text-neutral-900 dark:text-neutral-100 text-[10px] px-2 py-0.5 uppercase font-bold rounded">{banner.grid_type}</div>
                {!banner.is_active && (
                  <div className="absolute top-2 left-2 bg-black/70 text-white text-xs px-2 py-1 uppercase rounded">Inactive</div>
                )}
              </div>
              <div className="p-4">
                <div className="flex justify-between items-start">
                  <h3 className="font-semibold text-sm text-neutral-900 dark:text-neutral-100 truncate pr-2">{banner.title}</h3>
                  <div className="flex space-x-1 shrink-0">
                    <button onClick={() => movePromo(idx, 'up')} disabled={idx === 0} className="p-1 text-neutral-400 hover:text-brand-amber disabled:opacity-30"><ArrowUp className="w-4 h-4" /></button>
                    <button onClick={() => movePromo(idx, 'down')} disabled={idx === promoBanners.length - 1} className="p-1 text-neutral-400 hover:text-brand-amber disabled:opacity-30"><ArrowDown className="w-4 h-4" /></button>
                  </div>
                </div>
                <div className="flex justify-between items-center pt-3 mt-3 border-t border-neutral-100 dark:border-neutral-800">
                  <span className="text-xs font-mono text-neutral-400">Order: {banner.sort_order}</span>
                  <div className="flex space-x-3">
                    <button onClick={() => openPromoModal(banner)} className="text-neutral-500 dark:text-neutral-400 hover:text-brand-amber dark:hover:text-brand-amber text-xs font-medium flex items-center"><Edit className="w-3.5 h-3.5 mr-1" /> Edit</button>
                    <button onClick={() => deletePromoBanner(banner.id)} className="text-red-500 hover:text-red-700 text-xs font-medium flex items-center"><Trash2 className="w-3.5 h-3.5 mr-1" /> Delete</button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ANNOUNCEMENT */}
      {activeTab === 'announcement' && announcement && (
        <div className="max-w-2xl bg-white dark:bg-[#14151a] border border-neutral-200 dark:border-neutral-800 rounded-xl p-6 shadow-sm">
          <form onSubmit={saveAnnouncement} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">Announcement Text</label>
              <input
                type="text"
                value={announcement.text}
                onChange={e => setAnnouncement({...announcement, text: e.target.value})}
                className="w-full border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-brand-amber"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">Link URL (Optional)</label>
              <input
                type="text"
                value={announcement.link_url || ''}
                onChange={e => setAnnouncement({...announcement, link_url: e.target.value})}
                className="w-full border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-brand-amber"
                placeholder="/shop"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">Background Color</label>
                <div className="flex items-center space-x-2">
                  <input
                    type="color"
                    value={announcement.bg_color}
                    onChange={e => setAnnouncement({...announcement, bg_color: e.target.value})}
                    className="h-9 w-9 border-0 p-0 rounded cursor-pointer"
                  />
                  <input
                    type="text"
                    value={announcement.bg_color}
                    onChange={e => setAnnouncement({...announcement, bg_color: e.target.value})}
                    className="flex-1 border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg px-3 py-2 font-mono text-sm focus:outline-none"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">Text Color</label>
                <div className="flex items-center space-x-2">
                  <input
                    type="color"
                    value={announcement.text_color}
                    onChange={e => setAnnouncement({...announcement, text_color: e.target.value})}
                    className="h-9 w-9 border-0 p-0 rounded cursor-pointer"
                  />
                  <input
                    type="text"
                    value={announcement.text_color}
                    onChange={e => setAnnouncement({...announcement, text_color: e.target.value})}
                    className="flex-1 border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg px-3 py-2 font-mono text-sm focus:outline-none"
                  />
                </div>
              </div>
            </div>

            <div className="pt-2">
              <label className="flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={announcement.is_active}
                  onChange={(e) => setAnnouncement({ ...announcement, is_active: e.target.checked })}
