  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    if (!isAuthenticated) {
      router.push('/auth/login');
      return;
    }
    if (!isAdmin && !isOrderManager) {
      router.push('/account');
      return;
    }
  }, [isAuthenticated, isAdmin, isOrderManager, router]);

