              title={resolvedTheme === 'dark' ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
              aria-label="Toggle theme"
            >
              {resolvedTheme === 'dark' ? (
                <Sun className="w-4 h-4 text-amber-400 animate-scale-in" />
              ) : (
                <Moon className="w-4 h-4 text-neutral-600 animate-scale-in" />
