export default function OrdersManagementPage() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<OrderStatus | 'all'>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);
  const [newOrderAlert, setNewOrderAlert] = useState<Order | null>(null);
  const [page, setPage] = useState(1);
  const itemsPerPage = 15;

  const { formatAmount } = useCurrency();
  const { refreshData } = useStore();
  const { user, isAdmin, isOrderManager } = useAuth();

  const loadOrders = () => {
    const allOrders = DataStore.getOrders();
    allOrders.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
    setOrders(allOrders);
    setLoading(false);
  };

  useEffect(() => {
    loadOrders();

    // Setup Supabase Realtime Subscription for instant order updates
    if (isSupabaseConfigured) {
      const channel = supabase
        .channel('admin-orders-realtime')
        .on(
          'postgres_changes',
          { event: 'INSERT', schema: 'public', table: 'orders' },
          async (payload) => {
            console.log('⚡ [Realtime] New order placed:', payload);
            await DataStore.syncFromSupabase();
            loadOrders();
            if (payload.new) {
              setNewOrderAlert(payload.new as Order);
              setTimeout(() => setNewOrderAlert(null), 8000);
            }
          }
        )
        .on(
          'postgres_changes',
          { event: 'UPDATE', schema: 'public', table: 'orders' },
          async () => {
            console.log('⚡ [Realtime] Order status updated in Supabase');
            await DataStore.syncFromSupabase();
            loadOrders();
          }
        )
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, []);

  const handleUpdateStatus = async (
    orderId: string,
    newStatus: OrderStatus,
    customerNotes?: string,
    adminNotes?: string,
    courier?: string,
    trackingNumber?: string,
    trackingUrl?: string
  ) => {
    const res = await DataStore.updateOrderStatus(
      orderId,
      newStatus,
      customerNotes,
      courier,
      trackingNumber,
      trackingUrl
    );

    if (adminNotes) {
      const ordersList = DataStore.getOrders();
      const target = ordersList.find((o) => o.id === orderId);
      if (target) {
        target.admin_notes = adminNotes;
        if (isSupabaseConfigured) {
          supabase.from('orders').update({ admin_notes: adminNotes }).eq('id', orderId);
        }
      }
    }

    refreshData();
    loadOrders();
    return res;
  };

  const filteredOrders = orders.filter((order) => {
    const matchesFilter = filter === 'all' || order.status === filter;
    const matchesSearch =
      order.order_number.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (order.user_name || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
      (order.guest_email || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
      (order.shipping_address?.phone || '').includes(searchQuery);
    return matchesFilter && matchesSearch;
  });

  const handleExportOrdersCSV = () => {
    const headers = ['Order Number', 'Date', 'Customer', 'Email', 'Phone', 'Items Qty', 'Total Amount', 'Payment Method', 'Payment Status', 'Status', 'Courier', 'Tracking No'];
    const rows = filteredOrders.map((o) => [
      o.order_number,
      formatDate(o.created_at),
      o.user_name || o.guest_email || 'Guest',
      o.guest_email || '',
      o.shipping_address?.phone || o.guest_phone || '',
      o.items?.reduce((sum, i) => sum + i.quantity, 0) || 0,
      o.total_amount,
      o.payment_method?.toUpperCase(),
      o.payment_status?.toUpperCase(),
      o.status?.toUpperCase(),
      o.tracking_courier || '',
      o.tracking_number || '',
    ]);
    const csv = [headers.join(','), ...rows.map((r) => r.map((cell) => `"${cell}"`).join(','))].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `ozeira-orders-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const totalPages = Math.ceil(filteredOrders.length / itemsPerPage);
  const paginatedOrders = filteredOrders.slice((page - 1) * itemsPerPage, page * itemsPerPage);

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'pending':
        return 'bg-amber-100 dark:bg-amber-950/40 text-amber-800 dark:text-amber-300 border-amber-200 dark:border-amber-900/50';
      case 'confirmed':
        return 'bg-sky-100 dark:bg-sky-950/40 text-sky-800 dark:text-sky-300 border-sky-200 dark:border-sky-900/50';
      case 'processing':
        return 'bg-indigo-100 dark:bg-indigo-950/40 text-indigo-800 dark:text-indigo-300 border-indigo-200 dark:border-indigo-900/50';
      case 'shipped':
        return 'bg-blue-100 dark:bg-blue-950/40 text-blue-800 dark:text-blue-300 border-blue-200 dark:border-blue-900/50';
      case 'out_for_delivery':
        return 'bg-purple-100 dark:bg-purple-950/40 text-purple-800 dark:text-purple-300 border-purple-200 dark:border-purple-900/50';
      case 'delivered':
        return 'bg-emerald-100 dark:bg-emerald-950/40 text-emerald-800 dark:text-emerald-300 border-emerald-200 dark:border-emerald-900/50';
      case 'cancelled':
        return 'bg-rose-100 dark:bg-rose-950/40 text-rose-800 dark:text-rose-300 border-rose-200 dark:border-rose-900/50';
      case 'return_requested':
      case 'returned':
        return 'bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-300 border-neutral-300 dark:border-neutral-700';
      case 'refunded':
        return 'bg-red-100 dark:bg-red-950/40 text-red-800 dark:text-red-300 border-red-200 dark:border-red-900/50';
      default:
        return 'bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-300 border-neutral-200 dark:border-neutral-700';
    }
  };

  const tabs: { label: string; value: OrderStatus | 'all' }[] = [
    { label: 'All Orders', value: 'all' },
    { label: 'Placed', value: 'pending' },
    { label: 'Confirmed', value: 'confirmed' },
    { label: 'Processing', value: 'processing' },
    { label: 'Shipped', value: 'shipped' },
    { label: 'Out for Delivery', value: 'out_for_delivery' },
    { label: 'Delivered', value: 'delivered' },
    { label: 'Cancelled', value: 'cancelled' },
    { label: 'Refunded', value: 'refunded' },
  ];

  return (
    <div className="space-y-6">
      {/* Realtime New Order Floating Banner */}
      {newOrderAlert && (
        <div className="p-4 bg-gradient-to-r from-neutral-900 via-amber-950 to-neutral-900 text-white rounded-2xl shadow-xl border border-brand-amber/30 flex items-center justify-between animate-in slide-in-from-top-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-brand-amber/20 flex items-center justify-center text-amber-400">
              <Sparkles className="w-5 h-5 animate-spin" />
            </div>
            <div>
              <h4 className="text-sm font-bold text-brand-amber">
                ✨ New Order Received: #{newOrderAlert.order_number}
              </h4>
              <p className="text-xs text-neutral-300 mt-0.5">
                {newOrderAlert.user_name || newOrderAlert.guest_email} just placed an order for{' '}
                <strong className="text-white">₹{newOrderAlert.total_amount?.toLocaleString()}</strong> via{' '}
                {newOrderAlert.payment_method?.toUpperCase()}
              </p>
            </div>
          </div>
          <button
            onClick={() => {
              setExpandedOrderId(newOrderAlert.id);
              setNewOrderAlert(null);
            }}
            className="px-4 py-1.5 bg-brand-amber hover:bg-brand-amber-dark text-white text-xs font-bold uppercase tracking-wider rounded-xl transition-colors shadow-sm"
          >
            View Order →
          </button>
        </div>
      )}

      {/* Page Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-neutral-900 dark:text-neutral-100">
            Orders & Fulfillment
          </h1>
          <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-1">
            Real-time fulfillment, live carrier dispatching, customer notifications & refunds
          </p>
        </div>

        <div className="flex items-center gap-3">
          <button
            onClick={handleExportOrdersCSV}
            className="px-3.5 py-2 text-xs font-semibold text-neutral-700 dark:text-neutral-300 bg-white dark:bg-[#14151a] border border-neutral-200 dark:border-neutral-800 rounded-xl hover:bg-neutral-50 dark:hover:bg-neutral-800 flex items-center gap-1.5 shadow-sm transition-colors"
          >
            <Download className="w-3.5 h-3.5" />
            <span>Export Orders CSV</span>
          </button>
          {/* Realtime Live Indicator */}
          <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-emerald-50 dark:bg-emerald-950/40 border border-emerald-200 dark:border-emerald-900/50 rounded-full text-xs font-medium text-emerald-800 dark:text-emerald-300">
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
            </span>
            Realtime Live Sync
          </div>
        </div>
      </div>

      {/* Main Filter & Table Card */}
      <div className="bg-white dark:bg-[#14151a] rounded-2xl shadow-sm border border-neutral-200 dark:border-neutral-800 overflow-hidden">
        <div className="p-4 border-b border-neutral-100 dark:border-neutral-800 flex flex-col md:flex-row gap-4 items-center justify-between bg-neutral-50/50 dark:bg-neutral-900/50">
          {/* Status Tabs */}
          <div className="flex overflow-x-auto space-x-1.5 w-full md:w-auto pb-2 md:pb-0 hide-scrollbar">
            {tabs.map((tab) => (
              <button
                key={tab.value}
                onClick={() => {
                  setFilter(tab.value);
                  setPage(1);
                }}
                className={cn(
                  'px-3.5 py-1.5 text-xs font-semibold rounded-xl whitespace-nowrap transition-all uppercase tracking-wider',
                  filter === tab.value
                    ? 'bg-neutral-900 dark:bg-brand-amber text-white shadow-xs'
                    : 'bg-white dark:bg-neutral-900 text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800 border border-neutral-200 dark:border-neutral-700'
                )}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {/* Search Box */}
          <div className="relative w-full md:w-72">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-neutral-400" />
            <input
              type="text"
              placeholder="Search #, customer, email, phone..."
              className="w-full pl-9 pr-4 py-2 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 outline-none focus:border-brand-amber transition-colors"
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setPage(1);
              }}
            />
          </div>
        </div>

        {/* Orders Table */}
        {loading ? (
          <div className="p-8 space-y-4">
            {[1, 2, 3, 4, 5].map((i) => (
              <div key={i} className="h-16 bg-neutral-100 dark:bg-neutral-800 rounded-xl animate-pulse"></div>
            ))}
          </div>
        ) : filteredOrders.length === 0 ? (
          <div className="p-12 text-center text-neutral-400">
            <Package className="w-12 h-12 mx-auto mb-3 text-neutral-300 dark:text-neutral-700" />
            <p className="text-sm font-medium text-neutral-600 dark:text-neutral-400">No orders found matching your criteria.</p>
            <p className="text-xs text-neutral-400 mt-1">Try selecting another status tab or clear the search query.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs whitespace-nowrap">
              <thead className="bg-neutral-50 dark:bg-neutral-900 border-b border-neutral-200 dark:border-neutral-800 text-neutral-500 dark:text-neutral-400 font-semibold uppercase tracking-wider text-[10px]">
                <tr>
                  <th className="px-6 py-3.5">Order #</th>
                  <th className="px-6 py-3.5">Customer</th>
                  <th className="px-6 py-3.5">Date & Time</th>
                  <th className="px-6 py-3.5">Items</th>
                  <th className="px-6 py-3.5">Total Amount</th>
                  <th className="px-6 py-3.5">Payment</th>
                  <th className="px-6 py-3.5">Fulfillment Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-neutral-100 dark:divide-neutral-800">
                {paginatedOrders.map((order) => (
                  <React.Fragment key={order.id}>
                    <tr
                      className="hover:bg-brand-amber/5 dark:hover:bg-neutral-900/50 cursor-pointer transition-colors"
                      onClick={() => setExpandedOrderId(expandedOrderId === order.id ? null : order.id)}
                    >
                      <td className="px-6 py-4 font-bold text-neutral-900 dark:text-neutral-100">
                        <span className="text-brand-amber">{order.order_number}</span>
                        <ChevronDown
                          className={cn(
                            'inline-block ml-2 h-3.5 w-3.5 text-neutral-400 transition-transform',
                            expandedOrderId === order.id ? 'rotate-180 text-brand-amber' : ''
                          )}
                        />
                      </td>
                      <td className="px-6 py-4">
                        <div className="font-semibold text-neutral-900 dark:text-neutral-100">{order.user_name || order.shipping_address?.full_name}</div>
                        <div className="text-[11px] text-neutral-400">{order.guest_email || order.shipping_address?.phone}</div>
                      </td>
                      <td className="px-6 py-4 text-neutral-500 dark:text-neutral-400">{formatDate(order.created_at)}</td>
                      <td className="px-6 py-4 text-neutral-700 dark:text-neutral-300">
                        {order.items?.length || 0} {(order.items?.length || 0) === 1 ? 'piece' : 'pieces'}
                      </td>
                      <td className="px-6 py-4 font-bold text-neutral-900 dark:text-neutral-100">{formatAmount(order.total_amount)}</td>
                      <td className="px-6 py-4">
                        <span
                          className={cn(
                            'px-2 py-0.5 inline-flex text-[10px] font-bold uppercase rounded-md tracking-wider border',
                            order.payment_status === 'paid'
                              ? 'bg-emerald-50 dark:bg-emerald-950/40 text-emerald-800 dark:text-emerald-300 border-emerald-200 dark:border-emerald-900/50'
                              : 'bg-amber-50 dark:bg-amber-950/40 text-amber-800 dark:text-amber-300 border-amber-200 dark:border-amber-900/50'
                          )}
                        >
                          {order.payment_method?.toUpperCase()} • {order.payment_status?.toUpperCase()}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <span
                          className={cn(
                            'px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border inline-flex items-center gap-1.5',
                            getStatusBadge(order.status)
                          )}
                        >
                          <span className="w-1.5 h-1.5 rounded-full bg-current"></span>
                          {order.status.replace(/_/g, ' ')}
                        </span>
                      </td>
                    </tr>
                    {expandedOrderId === order.id && (
                      <tr>
                        <td colSpan={7} className="px-6 py-4 bg-neutral-50/60 dark:bg-neutral-900/60 border-y border-neutral-200 dark:border-neutral-800">
                          <OrderDetailView
                            order={order}
                            formatAmount={formatAmount}
                            onUpdateStatus={handleUpdateStatus}
                          />
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-6 py-3.5 border-t border-neutral-200 dark:border-neutral-800 flex items-center justify-between text-xs text-neutral-500 dark:text-neutral-400 bg-neutral-50/50 dark:bg-neutral-900/50">
            <span>
              Showing {(page - 1) * itemsPerPage + 1} to{' '}
              {Math.min(page * itemsPerPage, filteredOrders.length)} of {filteredOrders.length} entries
            </span>
            <div className="flex space-x-1.5">
              <button
                disabled={page === 1}
                onClick={() => setPage((p) => p - 1)}
                className="px-3 py-1 rounded-lg border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 font-medium disabled:opacity-40 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
              >
                Previous
              </button>
              <button
                disabled={page === totalPages}
                onClick={() => setPage((p) => p + 1)}
                className="px-3 py-1 rounded-lg border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 font-medium disabled:opacity-40 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
              >
                Next
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function OrderDetailView({
  order,
  formatAmount,
  onUpdateStatus,
}: {
  order: Order;
  formatAmount: (val: number) => string;
  onUpdateStatus: (
    id: string,
    status: OrderStatus,
    customerNotes?: string,
    adminNotes?: string,
    courier?: string,
    trackingNum?: string,
    trackingUrl?: string
  ) => Promise<any>;
}) {
  const [newStatus, setNewStatus] = useState<OrderStatus>(order.status);
  const [customerNotes, setCustomerNotes] = useState('');
  const [adminNotes, setAdminNotes] = useState(order.admin_notes || '');
  const [courier, setCourier] = useState(order.tracking_courier || 'Blue Dart Express');
  const [trackingNum, setTrackingNum] = useState(order.tracking_number || '');
  const [trackingUrl, setTrackingUrl] = useState(order.tracking_url || '');
  const [saveSuccessMsg, setSaveSuccessMsg] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showEmailPreview, setShowEmailPreview] = useState(false);
  const [isPushingSupplier, setIsPushingSupplier] = useState(false);

  const recipientTarget = order.guest_email || order.shipping_address?.phone || 'Customer';

  const handleAutoFulfillSupplier = async () => {
    setIsPushingSupplier(true);
    try {
      const res = await SupplierService.handleOrderPlaced(order);
      if (res.fulfillmentsCreated.length > 0) {
        const firstFul = res.fulfillmentsCreated[0];
        setSaveSuccessMsg(`🚀 Auto-fulfilled via ${firstFul.supplierName}! AWB: ${firstFul.trackingNumber || 'Processing'}`);
        if (firstFul.trackingNumber) {
          setTrackingNum(firstFul.trackingNumber);
          setCourier(firstFul.trackingCourier || 'Express Air');
          setNewStatus('shipped');
        }
      } else {
        setSaveSuccessMsg('⚠️ No items in this order are mapped to active suppliers. Map them in Suppliers & Dropship.');
      }
    } catch (err: any) {
      setSaveSuccessMsg(`❌ Supplier push failed: ${err?.message || 'Error'}`);
    } finally {
      setIsPushingSupplier(false);
      setTimeout(() => setSaveSuccessMsg(''), 7000);
    }
  };

  const handleSave = async () => {
    setIsSaving(true);
    const res = await onUpdateStatus(
      order.id,
      newStatus,
      customerNotes || undefined,
      adminNotes || undefined,
      courier,
      trackingNum,
      trackingUrl
    );
    const notif = res?.notification;
    if (notif?.emailSent) {
      setSaveSuccessMsg(`✅ Live email delivered to ${notif.recipient || recipientTarget}! Order updated to ${newStatus.toUpperCase()}`);
    } else if (notif?.simulated) {
      setSaveSuccessMsg(`⚠️ Status updated to ${newStatus.toUpperCase()} & saved to database, but live email was not sent because SMTP credentials are not configured in Store Settings.`);
    } else if (notif?.error) {
      setSaveSuccessMsg(`⚠️ Status updated to ${newStatus.toUpperCase()}, but email sending encountered an issue: ${notif.error}`);
    } else {
      setSaveSuccessMsg(`✨ Notification dispatched to ${recipientTarget}! Status updated to ${newStatus.toUpperCase()}`);
    }
    setIsSaving(false);
    setCustomerNotes('');
    setTimeout(() => setSaveSuccessMsg(''), 7000);
  };

  const handleQuickStatus = async (targetStatus: OrderStatus) => {
    setNewStatus(targetStatus);
    const res = await onUpdateStatus(
      order.id,
      targetStatus,
      `Order transitioned to ${targetStatus.replace(/_/g, ' ').toUpperCase()}`,
      adminNotes || undefined,
      courier,
      trackingNum,
      trackingUrl
    );
    const notif = res?.notification;
    if (notif?.emailSent) {
      setSaveSuccessMsg(`✅ Live email delivered to ${notif.recipient || recipientTarget}! Status updated to ${targetStatus.toUpperCase()}`);
    } else if (notif?.simulated) {
      setSaveSuccessMsg(`⚠️ Status updated to ${targetStatus.toUpperCase()} & saved to database, but live email was not sent because SMTP credentials are not configured in Store Settings.`);
    } else if (notif?.error) {
      setSaveSuccessMsg(`⚠️ Status updated to ${targetStatus.toUpperCase()}, but email sending failed: ${notif.error}`);
    } else {
      setSaveSuccessMsg(`✨ Notification dispatched to ${recipientTarget}! Status updated to ${targetStatus.toUpperCase()}`);
    }
    setTimeout(() => setSaveSuccessMsg(''), 7000);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 p-6 bg-white dark:bg-[#14151a] rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm text-neutral-900 dark:text-neutral-100">
      {/* Left 2 Cols: Order Items, Shipping Address & Cost Breakdown */}
      <div className="lg:col-span-2 space-y-6">
        {/* Lifecycle Stepper Navigation */}
        <div className="bg-neutral-50 dark:bg-neutral-900 p-4 rounded-xl border border-neutral-200 dark:border-neutral-800">
          <div className="text-[11px] font-bold uppercase tracking-wider text-neutral-500 dark:text-neutral-400 mb-3 flex items-center justify-between">
            <span>Fulfillment Pipeline Progression</span>
            <span className="text-brand-amber">Current: {order.status.replace(/_/g, ' ').toUpperCase()}</span>
          </div>
          <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
            {ORDER_LIFECYCLE_STEPS.map((step) => {
              const isCurrent = order.status === step.status;
              return (
                <button
                  key={step.status}
                  onClick={() => handleQuickStatus(step.status)}
                  className={cn(
                    'py-2 px-2 rounded-lg text-xs font-bold uppercase tracking-wider text-center border transition-all',
                    isCurrent
                      ? 'bg-brand-amber text-white border-brand-amber shadow-xs'
                      : 'bg-white dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 border-neutral-200 dark:border-neutral-700 hover:border-brand-amber hover:text-brand-amber'
                  )}
                >
                  {step.label}
                </button>
              );
            })}
          </div>
        </div>

        {/* Ordered Items Table */}
        <div>
          <h3 className="text-xs font-bold uppercase tracking-wider text-neutral-900 dark:text-neutral-100 border-b border-neutral-200 dark:border-neutral-800 pb-2 mb-3">
            Itemized Order Breakdown ({order.items?.length || 0})
          </h3>
          <div className="space-y-3">
            {(order.items || []).map((item) => (
              <div key={item.id} className="flex items-center space-x-4 bg-neutral-50/50 dark:bg-neutral-900/50 p-3 rounded-xl border border-neutral-100 dark:border-neutral-800">
                <img
                  src={item.product_image || 'https://images.unsplash.com/photo-1549465220-1a8b9238cd48?q=80&w=300'}
                  alt={item.product_title}
                  className="w-14 h-14 object-cover rounded-lg border border-neutral-200 dark:border-neutral-700"
                />
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-bold text-neutral-900 dark:text-neutral-100 truncate">{item.product_title}</p>
                  <p className="text-[11px] text-neutral-500 dark:text-neutral-400 mt-0.5">
                    {item.variant_details?.size && `Size: ${item.variant_details.size}`}
                    {item.variant_details?.color && ` • Color: ${item.variant_details.color}`}
                    {item.variant_details?.sku && ` • SKU: ${item.variant_details.sku}`}
                  </p>
                  <p className="text-xs text-neutral-600 dark:text-neutral-400 mt-1">
                    Qty: <strong>{item.quantity}</strong> × {formatAmount(item.unit_price)}
                  </p>
                </div>
                <div className="text-xs font-bold text-neutral-900 dark:text-neutral-100">{formatAmount(item.total_price)}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Address & Cost Summary */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-2">
          {/* Shipping Details */}
          <div className="bg-neutral-50 dark:bg-neutral-900 p-4 rounded-xl border border-neutral-200 dark:border-neutral-800">
            <h4 className="text-xs font-bold uppercase tracking-wider text-neutral-900 dark:text-neutral-100 mb-3 flex items-center gap-1.5">
              <MapPin className="w-3.5 h-3.5 text-brand-amber" /> Delivery Address
            </h4>
            <div className="text-xs text-neutral-600 dark:text-neutral-400 space-y-1 leading-relaxed">
              <p className="font-bold text-neutral-900 dark:text-neutral-100">{order.shipping_address?.full_name || order.user_name}</p>
              <p>{order.shipping_address?.street} {order.shipping_address?.apartment ? `, ${order.shipping_address?.apartment}` : ''}</p>
              <p>{order.shipping_address?.city}, {order.shipping_address?.state} {order.shipping_address?.postal_code}</p>
              <p className="font-semibold text-neutral-800 dark:text-neutral-200">{order.shipping_address?.country || 'India'}</p>
              <div className="pt-2 border-t border-neutral-200/80 dark:border-neutral-800 mt-2 space-y-1">
                <p className="flex items-center gap-1 text-neutral-700 dark:text-neutral-300">
                  <Phone className="w-3 h-3 text-neutral-400" /> {order.shipping_address?.phone || order.guest_phone || 'N/A'}
                </p>
                {order.guest_email && (
                  <p className="flex items-center gap-1 text-neutral-700 dark:text-neutral-300">
                    <Mail className="w-3 h-3 text-neutral-400" /> {order.guest_email}
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* Price Breakdown */}
          <div className="bg-neutral-50 dark:bg-neutral-900 p-4 rounded-xl border border-neutral-200 dark:border-neutral-800">
            <h4 className="text-xs font-bold uppercase tracking-wider text-neutral-900 dark:text-neutral-100 mb-3">Financial Settlement</h4>
            <div className="space-y-2 text-xs">
              <div className="flex justify-between text-neutral-600 dark:text-neutral-400">
                <span>Subtotal</span>
                <span>{formatAmount(order.subtotal)}</span>
              </div>
              {order.discount_amount > 0 && (
                <div className="flex justify-between text-emerald-600 dark:text-emerald-400 font-medium">
                  <span>Discount ({order.coupon_code || 'Promo'})</span>
                  <span>-{formatAmount(order.discount_amount)}</span>
                </div>
              )}
              {order.loyalty_discount_amount > 0 && (
                <div className="flex justify-between text-brand-amber font-medium">
                  <span>Loyalty Points Discount</span>
                  <span>-{formatAmount(order.loyalty_discount_amount)}</span>
                </div>
              )}
              <div className="flex justify-between text-neutral-600 dark:text-neutral-400">
                <span>Shipping Fee</span>
                <span>{order.shipping_fee > 0 ? formatAmount(order.shipping_fee) : 'Complimentary'}</span>
              </div>
              <div className="flex justify-between text-neutral-600 dark:text-neutral-400">
                <span>Tax (GST 12%)</span>
                <span>{formatAmount(order.tax_amount)}</span>
              </div>
              <div className="flex justify-between font-bold text-neutral-900 dark:text-neutral-100 pt-2 border-t border-neutral-200 dark:border-neutral-800 text-sm">
                <span>Total Amount</span>
                <span className="text-brand-amber">{formatAmount(order.total_amount)}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Right Column: Manage Status, Carrier Tracking & Staff Notes */}
      <div className="space-y-6">
        <div className="bg-neutral-50 dark:bg-neutral-900 p-5 rounded-xl border border-neutral-200 dark:border-neutral-800">
          <h3 className="text-xs font-bold uppercase tracking-wider text-neutral-900 dark:text-neutral-100 mb-4 flex items-center gap-1.5">
            <Truck className="w-4 h-4 text-brand-amber" /> State Transition & Dispatch
          </h3>

          <div className="space-y-4">
            {/* Status Select */}
            <div>
              <label className="block text-[11px] font-bold uppercase tracking-wider text-neutral-700 dark:text-neutral-300 mb-1">
                Fulfillment Status
              </label>
              <select
                value={newStatus}
                onChange={(e) => setNewStatus(e.target.value as OrderStatus)}
                className="w-full border border-neutral-300 dark:border-neutral-700 rounded-xl focus:border-brand-amber text-xs font-medium bg-white dark:bg-neutral-800 text-neutral-900 dark:text-neutral-100 p-2.5 outline-none"
              >
                <option value="pending">Placed (Pending)</option>
                <option value="confirmed">Confirmed</option>
                <option value="processing">Processing in Atelier</option>
                <option value="shipped">Shipped (In Transit)</option>
                <option value="out_for_delivery">Out for Delivery</option>
                <option value="delivered">Delivered to Patron</option>
                <option value="cancelled">Cancelled</option>
                <option value="return_requested">Return Requested</option>
                <option value="returned">Returned</option>
                <option value="refunded">Refunded</option>
              </select>
            </div>

            {/* Courier Dispatch Fields */}
            {(newStatus === 'shipped' || newStatus === 'out_for_delivery' || order.tracking_number) && (
              <div className="space-y-3 p-3.5 bg-white dark:bg-neutral-950/40 rounded-xl border border-neutral-200 dark:border-neutral-800 shadow-2xs">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-neutral-500">Logistics & AWB</span>
                  <button
                    type="button"
                    onClick={() => {
                      const num = `BD-OZ${order.order_number.replace(/[^0-9]/g, '')}-${Math.floor(100000 + Math.random() * 900000)}`;
                      setTrackingNum(num);
                      setCourier('Blue Dart Express');
                      setTrackingUrl(`http://localhost:3000/track-order?orderNumber=${order.order_number}&email=${encodeURIComponent(order.guest_email || '')}`);
                    }}
                    className="text-[10px] font-bold uppercase text-brand-amber hover:underline flex items-center gap-1"
                  >
                    <Sparkles className="w-3 h-3" /> Auto-Generate AWB
                  </button>
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-wider text-neutral-700 dark:text-neutral-300 mb-1">
                    Courier Partner
                  </label>
                  <input
                    type="text"
                    value={courier}
                    onChange={(e) => setCourier(e.target.value)}
                    className="w-full border border-neutral-300 dark:border-neutral-700 rounded-lg text-xs p-2 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 outline-none focus:border-brand-amber"
                    placeholder="e.g. Blue Dart, Delhivery, DHL"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-wider text-neutral-700 dark:text-neutral-300 mb-1">
                    AWB / Tracking Number
                  </label>
                  <input
                    type="text"
                    value={trackingNum}
                    onChange={(e) => setTrackingNum(e.target.value)}
                    className="w-full border border-neutral-300 dark:border-neutral-700 rounded-lg text-xs p-2 font-mono bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 outline-none focus:border-brand-amber"
                    placeholder="e.g. BLUEDART-99281726"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-wider text-neutral-700 dark:text-neutral-300 mb-1">
                    Tracking URL
                  </label>
                  <input
                    type="url"
                    value={trackingUrl}
                    onChange={(e) => setTrackingUrl(e.target.value)}
                    className="w-full border border-neutral-300 dark:border-neutral-700 rounded-lg text-xs p-2 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 outline-none focus:border-brand-amber"
                    placeholder="https://track.bluedart.com/..."
                  />
                </div>
              </div>
            )}

            {/* Customer Notification Note */}
            <div>
              <label className="block text-[11px] font-bold uppercase tracking-wider text-neutral-700 dark:text-neutral-300 mb-1">
                Customer Email Note <span className="text-neutral-400 font-normal">(Sent via Email/SMS)</span>
              </label>
              <textarea
                value={customerNotes}
                onChange={(e) => setCustomerNotes(e.target.value)}
                className="w-full border border-neutral-300 dark:border-neutral-700 rounded-xl text-xs p-2.5 bg-white dark:bg-neutral-800 text-neutral-900 dark:text-neutral-100 outline-none focus:border-brand-amber"
                rows={2}
                placeholder="e.g. Dispatched with tamper-proof security seal."
              />
            </div>

            {/* Internal Staff Notes (Visible only to Admin) */}
            <div>
              <label className="block text-[11px] font-bold uppercase tracking-wider text-neutral-700 dark:text-neutral-300 mb-1 flex items-center justify-between">
                <span>Internal Staff Note</span>
                <span className="text-[10px] text-amber-700 dark:text-amber-300 bg-amber-100 dark:bg-amber-950/40 px-1.5 py-0.5 rounded font-bold">Admin Only</span>
              </label>
              <textarea
                value={adminNotes}
                onChange={(e) => setAdminNotes(e.target.value)}
                className="w-full border border-neutral-300 dark:border-neutral-700 rounded-xl text-xs p-2.5 bg-white dark:bg-neutral-800 text-neutral-900 dark:text-neutral-100 outline-none focus:border-brand-amber"
                rows={2}
                placeholder="Internal verification notes..."
              />
            </div>

            {saveSuccessMsg && (
              <div className="p-3 bg-emerald-50 dark:bg-emerald-950/40 text-emerald-800 dark:text-emerald-300 rounded-xl border border-emerald-200 dark:border-emerald-900/50 text-xs font-semibold flex items-center gap-2 animate-in fade-in">
                <CheckCircle2 className="w-4 h-4 text-emerald-600 dark:text-emerald-400 shrink-0" />
                <span>{saveSuccessMsg}</span>
              </div>
            )}

            {/* Save Button */}
            <button
              onClick={handleSave}
              disabled={isSaving}
              className="w-full py-3 px-4 rounded-xl text-xs font-bold uppercase tracking-wider text-white bg-brand-amber hover:bg-brand-amber-dark transition-all shadow-md flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50"
            >
              {isSaving ? (
                <>
                  <Sparkles className="w-3.5 h-3.5 animate-spin" /> Dispatching Notification...
                </>
              ) : (
                <>
                  <Send className="w-3.5 h-3.5" /> Commit Order Update & Notify
                </>
              )}
            </button>

            {/* Auto-Fulfill via Supplier Integration Action */}
            <button
              type="button"
              onClick={handleAutoFulfillSupplier}
              disabled={isPushingSupplier}
              className="w-full py-2.5 px-3 rounded-xl text-xs font-bold uppercase tracking-wider text-stone-900 dark:text-stone-100 bg-amber-50 dark:bg-amber-950/40 hover:bg-amber-100 dark:hover:bg-amber-900/50 border border-amber-300 dark:border-amber-800/60 transition-all flex items-center justify-center gap-1.5 shadow-2xs cursor-pointer disabled:opacity-50"
            >
              <Zap className="w-3.5 h-3.5 text-brand-amber" />
              {isPushingSupplier ? 'Routing to Supplier API...' : 'Auto-Route to CJ / DeoDap'}
            </button>

            {/* Preview Email Template Action */}
            <button
              type="button"
              onClick={() => setShowEmailPreview(!showEmailPreview)}
              className="w-full py-2 px-3 rounded-lg text-xs font-semibold text-neutral-600 dark:text-neutral-400 bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700 border border-neutral-200 dark:border-neutral-700 transition-all flex items-center justify-center gap-1.5 cursor-pointer"
            >
              <Eye className="w-3.5 h-3.5 text-brand-amber" />
              {showEmailPreview ? 'Hide Customer Email Preview' : 'Preview Customer Email Template'}
            </button>

            {/* Download Tax Invoice Link */}
            <a
              href={`/api/invoice/${order.id}`}
              target="_blank"
              rel="noopener noreferrer"
              className="w-full py-2 px-3 rounded-lg text-xs font-semibold text-neutral-800 dark:text-neutral-200 bg-white dark:bg-[#1c1d22] hover:bg-neutral-50 dark:hover:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 transition-all flex items-center justify-center gap-1.5 shadow-xs"
            >
              <FileText className="w-3.5 h-3.5 text-brand-amber" />
              Download GST Tax Invoice (PDF)
            </a>

            {/* Email Preview Drawer */}
            {showEmailPreview && (
              <div className="p-3.5 bg-white dark:bg-neutral-900 rounded-xl border border-neutral-300 dark:border-neutral-700 text-xs space-y-2 animate-in fade-in">
                <div className="flex items-center justify-between pb-2 border-b border-neutral-100 dark:border-neutral-800">
                  <span className="font-bold text-neutral-900 dark:text-neutral-100 flex items-center gap-1.5">
                    <Mail className="w-3.5 h-3.5 text-brand-amber" /> Outbound Email Preview
                  </span>
                  <span className="text-[10px] text-neutral-500 dark:text-neutral-400 font-mono">To: {order.guest_email || 'patron@example.com'}</span>
                </div>
                <div className="max-h-60 overflow-y-auto rounded border border-neutral-200 dark:border-neutral-800 bg-[#fdfbf9] dark:bg-black/30 p-2 text-[11px] text-neutral-900 dark:text-neutral-100">
                  <div
                    dangerouslySetInnerHTML={{
                      __html: NotificationService.generateOrderEmail(
                        { ...order, status: newStatus, tracking_courier: courier, tracking_number: trackingNum, tracking_url: trackingUrl },
                        `order_${newStatus}`,
                        customerNotes
                      ).html,
                    }}
                  />
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Status Audit History */}
        <div>
          <h4 className="text-xs font-bold uppercase tracking-wider text-neutral-900 dark:text-neutral-100 border-b border-neutral-200 dark:border-neutral-800 pb-2 mb-3">
            Audit Timeline & Status Log
          </h4>
          <div className="space-y-3 max-h-56 overflow-y-auto pr-2 text-xs">
            {(order.status_history || []).slice().reverse().map((history) => (
              <div key={history.id} className="relative pl-4 border-l-2 border-brand-amber/40 pb-2">
                <div className="absolute w-2 h-2 bg-brand-amber rounded-full -left-[5px] top-1.5" />
                <p className="font-bold text-neutral-900 dark:text-neutral-100 uppercase text-[11px] tracking-wider">
                  {history.status.replace(/_/g, ' ')}
                </p>
                <p className="text-[10px] text-neutral-400">{formatDateTime(history.created_at)}</p>
                {history.notes && <p className="text-neutral-600 dark:text-neutral-400 mt-1 bg-neutral-50 dark:bg-neutral-800/60 p-2 rounded-lg border border-neutral-100 dark:border-neutral-800">{history.notes}</p>}
                <p className="text-[10px] text-neutral-400 mt-0.5 font-medium">Updated by {history.updated_by}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState, useMemo } from 'react';
import Link from 'next/link';
import { DataStore } from '@/lib/store/data-store';
import { useCurrency } from '@/lib/context/CurrencyLanguageContext';
import { formatDate, cn } from '@/lib/utils';
import {
  DollarSign,
  ShoppingCart,
  Users,
  Package,
  TrendingUp,
  TrendingDown,
  ArrowUpRight,
  Clock,
  AlertTriangle,
  Star,
  Eye,
  ChevronRight,
  BarChart3,
  Activity,
} from 'lucide-react';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';

interface KPICard {
  title: string;
  value: string;
  change: string;
  changeType: 'positive' | 'negative' | 'neutral';
  icon: React.ElementType;
  iconColor: string;
  iconBg: string;
}

export default function AdminDashboard() {
  const { formatPriceValue } = useCurrency();
  const [mounted, setMounted] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  useEffect(() => {
    setMounted(true);

    if (isSupabaseConfigured) {
      const channel = supabase
        .channel('admin-dashboard-realtime')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, async () => {
          await DataStore.syncFromSupabase();
          setRefreshTrigger((prev) => prev + 1);
        })
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, []);

  const data = useMemo(() => {
    if (!mounted) return null;
    const _ = refreshTrigger;

    const orders = DataStore.getOrders();
    const products = DataStore.getProducts();
    const users = DataStore.getUsers();
    const reviews = DataStore.getReviews();

    const totalRevenue = orders
      .filter((o) => o.payment_status === 'paid' || o.status === 'delivered')
      .reduce((sum, o) => sum + o.total_amount, 0);

    const totalOrders = orders.length;
    const pendingOrders = orders.filter((o) => o.status === 'pending').length;
    const shippedOrders = orders.filter((o) => o.status === 'shipped').length;
    const deliveredOrders = orders.filter((o) => o.status === 'delivered').length;
    const cancelledOrders = orders.filter((o) => o.status === 'cancelled').length;
    const totalCustomers = users.filter((u) => u.role === 'customer').length;
    const totalProducts = products.length;
    const lowStockProducts = products.filter((p) => p.total_stock > 0 && p.total_stock <= 5);
    const outOfStockProducts = products.filter((p) => p.total_stock === 0);
    const pendingReviews = reviews.filter((r) => r.status === 'pending');
    const avgOrderValue = totalOrders > 0 ? totalRevenue / totalOrders : 0;

    const recentOrders = [...orders]
      .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())
      .slice(0, 5);

    // Compute dynamic real 7-day metrics
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const revenueChart = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - (6 - i));
      const dayStr = d.toISOString().split('T')[0];
      const dayOrders = orders.filter((o) => o.created_at?.startsWith(dayStr));
      const dayRevenue = dayOrders
        .filter((o) => o.payment_status === 'paid' || o.status === 'delivered')
        .reduce((sum, o) => sum + o.total_amount, 0);

      return {
        day: days[d.getDay()],
        date: dayStr,
        revenue: dayRevenue,
        orderCount: dayOrders.length,
      };
    });

    const maxChartValue = Math.max(...revenueChart.map((r) => r.revenue), 1000);

    return {
      totalRevenue,
      totalOrders,
      pendingOrders,
      shippedOrders,
      deliveredOrders,
      cancelledOrders,
      totalCustomers,
      totalProducts,
      lowStockProducts,
      outOfStockProducts,
      pendingReviews,
      avgOrderValue,
      recentOrders,
      revenueChart,
      maxChartValue,
      orders,
      products,
    };
  }, [mounted, refreshTrigger]);

  if (!mounted || !data) {
    return (
      <div className="animate-pulse space-y-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="bg-white dark:bg-[#14151a] rounded-xl h-32 border border-neutral-200 dark:border-neutral-800" />
          ))}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white dark:bg-[#14151a] rounded-xl h-80 border border-neutral-200 dark:border-neutral-800" />
          <div className="bg-white dark:bg-[#14151a] rounded-xl h-80 border border-neutral-200 dark:border-neutral-800" />
        </div>
      </div>
    );
  }

  const kpis: KPICard[] = [
    {
      title: 'Total Revenue',
      value: formatPriceValue(data.totalRevenue),
      change: data.totalRevenue > 0 ? 'Live Invoiced' : '₹0.00 Initial',
      changeType: 'positive',
      icon: DollarSign,
      iconColor: 'text-emerald-600 dark:text-emerald-400',
      iconBg: 'bg-emerald-50 dark:bg-emerald-950/40',
    },
    {
      title: 'Total Orders',
      value: data.totalOrders.toString(),
      change: data.totalOrders > 0 ? `${data.totalOrders} Active` : '0 Recorded',
      changeType: 'positive',
      icon: ShoppingCart,
      iconColor: 'text-blue-600 dark:text-blue-400',
      iconBg: 'bg-blue-50 dark:bg-blue-950/40',
    },
    {
      title: 'Registered Patrons',
      value: data.totalCustomers.toString(),
      change: data.totalCustomers > 0 ? `${data.totalCustomers} Accounts` : '0 Customers',
      changeType: 'positive',
      icon: Users,
      iconColor: 'text-violet-600 dark:text-violet-400',
      iconBg: 'bg-violet-50 dark:bg-violet-950/40',
    },
    {
      title: 'Avg. Order Value',
      value: formatPriceValue(data.avgOrderValue),
      change: data.avgOrderValue > 0 ? 'Computed AOV' : 'N/A',
      changeType: 'neutral',
      icon: TrendingUp,
      iconColor: 'text-amber-600 dark:text-amber-400',
      iconBg: 'bg-amber-50 dark:bg-amber-950/40',
    },
  ];

  const statusConfig: Record<string, { label: string; color: string; bg: string }> = {
    pending: {
      label: 'Pending',
      color: 'text-yellow-700 dark:text-yellow-300',
      bg: 'bg-yellow-50 dark:bg-yellow-950/40 border-yellow-200 dark:border-yellow-900/60',
    },
    confirmed: {
      label: 'Confirmed',
      color: 'text-blue-700 dark:text-blue-300',
      bg: 'bg-blue-50 dark:bg-blue-950/40 border-blue-200 dark:border-blue-900/60',
    },
    shipped: {
      label: 'Shipped',
      color: 'text-indigo-700 dark:text-indigo-300',
      bg: 'bg-indigo-50 dark:bg-indigo-950/40 border-indigo-200 dark:border-indigo-900/60',
    },
    out_for_delivery: {
      label: 'Out for Delivery',
      color: 'text-purple-700 dark:text-purple-300',
      bg: 'bg-purple-50 dark:bg-purple-950/40 border-purple-200 dark:border-purple-900/60',
    },
    delivered: {
      label: 'Delivered',
      color: 'text-green-700 dark:text-green-300',
      bg: 'bg-green-50 dark:bg-green-950/40 border-green-200 dark:border-green-900/60',
    },
    cancelled: {
      label: 'Cancelled',
      color: 'text-red-700 dark:text-red-300',
      bg: 'bg-red-50 dark:bg-red-950/40 border-red-200 dark:border-red-900/60',
    },
    returned: {
      label: 'Returned',
      color: 'text-neutral-700 dark:text-neutral-300',
      bg: 'bg-neutral-50 dark:bg-neutral-900 border-neutral-200 dark:border-neutral-800',
    },
  };

  const orderStatusBreakdown = [
    { status: 'Pending', count: data.pendingOrders, color: 'bg-yellow-400' },
    { status: 'Shipped', count: data.shippedOrders, color: 'bg-indigo-400' },
    { status: 'Delivered', count: data.deliveredOrders, color: 'bg-green-400' },
    { status: 'Cancelled', count: data.cancelledOrders, color: 'bg-red-400' },
  ];

  return (
    <div className="space-y-6">
      {/* Page header */}
      <div>
        <h1 className="text-2xl font-bold text-neutral-900 dark:text-neutral-100">Live Atelier Dashboard</h1>
        <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-1">
          Real-time metrics, catalog health, and live customer order fulfillment.
        </p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {kpis.map((kpi) => {
          const Icon = kpi.icon;
          return (
            <div
              key={kpi.title}
              className="bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 p-5 hover:shadow-md transition-shadow"
            >
              <div className="flex items-start justify-between">
                <div className={cn('w-10 h-10 rounded-lg flex items-center justify-center', kpi.iconBg)}>
                  <Icon className={cn('w-5 h-5', kpi.iconColor)} />
                </div>
                <span
                  className={cn(
                    'text-xs font-medium flex items-center gap-1 px-2 py-0.5 rounded-full',
                    kpi.changeType === 'positive'
                      ? 'text-emerald-700 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/50'
                      : 'text-neutral-600 dark:text-neutral-400 bg-neutral-100 dark:bg-neutral-800'
                  )}
                >
                  ● {kpi.change}
                </span>
              </div>
              <div className="mt-3">
                <p className="text-2xl font-bold text-neutral-900 dark:text-neutral-100">{kpi.value}</p>
                <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-0.5">{kpi.title}</p>
              </div>
            </div>
          );
        })}
      </div>

      {/* Charts + Alerts row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Revenue chart */}
        <div className="lg:col-span-2 bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 p-5">
          <div className="flex items-center justify-between mb-6">
            <div>
              <h3 className="font-semibold text-neutral-900 dark:text-neutral-100">Revenue Overview</h3>
              <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">
                Last 7 days real transaction volume
              </p>
            </div>
            <div className="flex items-center gap-1.5 text-xs text-emerald-600 dark:text-emerald-400 font-semibold bg-emerald-50 dark:bg-emerald-950/40 px-2 py-1 rounded-full">
              <Activity className="w-3.5 h-3.5" />
              <span>Realtime Live</span>
            </div>
          </div>
          <div className="flex items-end gap-3 h-48">
            {data.revenueChart.map((bar) => {
              const heightPct =
                data.totalRevenue > 0
                  ? Math.max((bar.revenue / data.maxChartValue) * 100, bar.revenue > 0 ? 15 : 4)
                  : 4;
              return (
                <div key={bar.day} className="flex-1 flex flex-col items-center gap-2">
                  <div className="w-full flex justify-center h-36 items-end">
                    <div
                      className="w-full max-w-[36px] bg-brand-amber/20 hover:bg-brand-amber/40 dark:bg-stone-800 dark:hover:bg-stone-700 rounded-t-md transition-all cursor-pointer relative group"
                      style={{ height: `${heightPct}%` }}
                    >
                      <div
                        className="absolute bottom-0 left-0 right-0 bg-[#c46331] rounded-t-md transition-all"
                        style={{ height: bar.revenue > 0 ? '100%' : '0%' }}
                      />
                      <div className="absolute -top-7 left-1/2 -translate-x-1/2 bg-neutral-900 text-white text-[10px] px-1.5 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-10 shadow-md">
                        {formatPriceValue(bar.revenue)} ({bar.orderCount} orders)
                      </div>
                    </div>
                  </div>
                  <span className="text-xs text-neutral-500 dark:text-neutral-400 font-medium">{bar.day}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Order status breakdown */}
        <div className="bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 p-5">
          <h3 className="font-semibold text-neutral-900 dark:text-neutral-100 mb-1">Order Pipeline</h3>
          <p className="text-xs text-neutral-500 dark:text-neutral-400 mb-4">Distribution by status</p>
          <div className="space-y-3">
            {orderStatusBreakdown.map((item) => (
              <div key={item.status} className="flex items-center justify-between">
                <div className="flex items-center gap-2.5">
                  <div className={cn('w-3 h-3 rounded-full', item.color)} />
                  <span className="text-sm text-neutral-700 dark:text-neutral-300">{item.status}</span>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-24 h-1.5 bg-neutral-100 dark:bg-neutral-800 rounded-full overflow-hidden">
                    <div
                      className={cn('h-full rounded-full', item.color)}
                      style={{ width: `${data.totalOrders > 0 ? (item.count / data.totalOrders) * 100 : 0}%` }}
                    />
                  </div>
                  <span className="text-sm font-semibold text-neutral-900 dark:text-neutral-100 w-6 text-right">
                    {item.count}
                  </span>
                </div>
              </div>
            ))}
          </div>
          <div className="mt-4 pt-4 border-t border-neutral-100 dark:border-neutral-800">
            <div className="flex items-center justify-between text-sm">
              <span className="text-neutral-500 dark:text-neutral-400">Total Live Orders</span>
              <span className="font-bold text-neutral-900 dark:text-neutral-100">{data.totalOrders}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Recent Orders + Alerts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Recent Orders */}
        <div className="lg:col-span-2 bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800">
          <div className="flex items-center justify-between p-5 border-b border-neutral-100 dark:border-neutral-800">
            <h3 className="font-semibold text-neutral-900 dark:text-neutral-100">Recent Orders</h3>
            <Link
              href="/admin/orders"
              className="text-xs text-[#c46331] hover:underline font-medium flex items-center gap-1"
            >
              View All
              <ChevronRight className="w-3.5 h-3.5" />
            </Link>
          </div>
          <div className="divide-y divide-neutral-100 dark:divide-neutral-800">
            {data.recentOrders.length === 0 ? (
              <div className="p-8 text-center text-neutral-400">
                <ShoppingCart className="w-10 h-10 mx-auto mb-2 opacity-50" />
                <p className="text-sm font-medium">No customer orders recorded yet</p>
                <p className="text-xs text-neutral-500 mt-1">Live orders placed by patrons will automatically display here in real-time.</p>
              </div>
            ) : (
              data.recentOrders.map((order) => {
                const statusConf = statusConfig[order.status] || statusConfig.pending;
                return (
                  <div
                    key={order.id}
                    className="flex items-center justify-between px-5 py-3.5 hover:bg-neutral-50 dark:hover:bg-[#1c1a17] transition-colors"
                  >
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="w-9 h-9 bg-neutral-100 dark:bg-neutral-800 rounded-lg flex items-center justify-center flex-shrink-0">
                        <ShoppingCart className="w-4 h-4 text-neutral-500" />
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-medium text-neutral-900 dark:text-neutral-100 truncate">
                          {order.order_number}
                        </p>
                        <p className="text-xs text-neutral-500 dark:text-neutral-400">
                          {order.user_name || order.guest_email || 'Guest'} · {formatDate(order.created_at)}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      <span
                        className={cn(
                          'text-[11px] font-medium px-2 py-1 rounded-full border',
                          statusConf.bg,
                          statusConf.color
                        )}
                      >
                        {statusConf.label}
                      </span>
                      <span className="text-sm font-semibold text-neutral-900 dark:text-neutral-100 w-24 text-right">
                        {formatPriceValue(order.total_amount)}
                      </span>
                      <Link
                        href={`/admin/orders`}
                        className="p-1.5 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
                      >
                        <Eye className="w-4 h-4" />
                      </Link>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Alerts panel */}
        <div className="space-y-4">
          {/* Low stock alert */}
          {data.lowStockProducts.length > 0 && (
            <div className="bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 p-5">
              <div className="flex items-center gap-2 mb-3">
                <AlertTriangle className="w-4 h-4 text-amber-500" />
                <h3 className="font-semibold text-neutral-900 dark:text-neutral-100 text-sm">Low Stock Alert</h3>
              </div>
              <div className="space-y-2">
                {data.lowStockProducts.slice(0, 5).map((p) => (
                  <div key={p.id} className="flex items-center justify-between text-sm">
                    <span className="text-neutral-700 dark:text-neutral-300 truncate max-w-[160px]">{p.title}</span>
                    <span className="text-amber-600 dark:text-amber-400 font-medium">{p.total_stock} left</span>
                  </div>
                ))}
              </div>
              {data.lowStockProducts.length > 5 && (
                <Link href="/admin/products" className="text-xs text-[#c46331] hover:underline mt-2 block">
                  +{data.lowStockProducts.length - 5} more items
                </Link>
              )}
            </div>
          )}

          {/* Out of stock */}
          {data.outOfStockProducts.length > 0 && (
            <div className="bg-white dark:bg-[#14151a] rounded-xl border border-red-200 dark:border-red-900/60 p-5">
              <div className="flex items-center gap-2 mb-3">
                <Package className="w-4 h-4 text-red-500" />
                <h3 className="font-semibold text-neutral-900 dark:text-neutral-100 text-sm">Out of Stock</h3>
              </div>
              <div className="space-y-2">
                {data.outOfStockProducts.slice(0, 3).map((p) => (
                  <div key={p.id} className="flex items-center justify-between text-sm">
                    <span className="text-neutral-700 dark:text-neutral-300 truncate max-w-[160px]">{p.title}</span>
                    <span className="text-red-500 font-medium text-xs">Out of Stock</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Pending reviews */}
          {data.pendingReviews.length > 0 && (
            <div className="bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 p-5">
              <div className="flex items-center gap-2 mb-3">
                <Star className="w-4 h-4 text-violet-500" />
                <h3 className="font-semibold text-neutral-900 dark:text-neutral-100 text-sm">Pending Reviews</h3>
              </div>
              <p className="text-sm text-neutral-600 dark:text-neutral-400">
                <span className="font-semibold text-violet-600 dark:text-violet-400">{data.pendingReviews.length}</span> reviews waiting for moderation
              </p>
              <Link href="/admin/reviews" className="text-xs text-[#c46331] hover:underline mt-2 block">
                Review now →
              </Link>
            </div>
          )}

          {/* Quick actions */}
          <div className="bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 p-5">
            <h3 className="font-semibold text-neutral-900 dark:text-neutral-100 text-sm mb-3">Quick Actions</h3>
            <div className="space-y-2">
              {[
                { label: 'Add New Product', href: '/admin/products', icon: Package },
                { label: 'View All Orders', href: '/admin/orders', icon: ShoppingCart },
                { label: 'Manage Banners', href: '/admin/banners', icon: BarChart3 },
                { label: 'Store Settings', href: '/admin/settings', icon: Clock },
              ].map((action) => {
                const Icon = action.icon;
                return (
                  <Link
                    key={action.href}
                    href={action.href}
                    className="flex items-center gap-2.5 px-3 py-2 text-sm text-neutral-700 dark:text-neutral-300 hover:bg-neutral-50 dark:hover:bg-[#1c1a17] hover:text-neutral-900 dark:hover:text-neutral-100 rounded-lg transition-colors"
                  >
                    <Icon className="w-4 h-4 text-neutral-400" />
                    {action.label}
                    <ArrowUpRight className="w-3 h-3 ml-auto text-neutral-300" />
                  </Link>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo, useEffect } from 'react';
import Link from 'next/link';
import { DataStore } from '@/lib/store/data-store';
import { useCurrency } from '@/lib/context/CurrencyLanguageContext';
import { useStore } from '@/lib/context/StoreContext';
import { cn, formatDate } from '@/lib/utils';
import { Product, Category } from '@/types';
import {
  Plus,
  Search,
  Filter,
  Download,
  Upload,
  Edit2,
  Trash2,
  Eye,
  MoreVertical,
  Package,
  ChevronLeft,
  ChevronRight,
  AlertTriangle,
  Check,
  X,
  Image as ImageIcon,
  Star,
  Copy,
} from 'lucide-react';
import { ImageUploadDropzone } from '@/components/common/ImageUploadDropzone';

type ViewMode = 'list' | 'grid';
type StockFilter = 'all' | 'in_stock' | 'low_stock' | 'out_of_stock';

export default function AdminProductsPage() {
  const { formatPriceValue } = useCurrency();
  const { categories, refreshData } = useStore();
  const [mounted, setMounted] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [stockFilter, setStockFilter] = useState<StockFilter>('all');
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const itemsPerPage = 10;

  useEffect(() => {
    setMounted(true);
    setProducts(DataStore.getProducts());
  }, []);

  const filtered = useMemo(() => {
    let result = [...products];
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter(p =>
        p.title.toLowerCase().includes(q) ||
        p.sku.toLowerCase().includes(q) ||
        p.brand.toLowerCase().includes(q)
      );
    }
    if (categoryFilter !== 'all') {
      result = result.filter(p => p.category_id === categoryFilter);
    }
    if (stockFilter === 'in_stock') result = result.filter(p => p.total_stock > 5);
    if (stockFilter === 'low_stock') result = result.filter(p => p.total_stock > 0 && p.total_stock <= 5);
    if (stockFilter === 'out_of_stock') result = result.filter(p => p.total_stock === 0);
    return result;
  }, [products, searchQuery, categoryFilter, stockFilter]);

  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const paginated = filtered.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    next.has(id) ? next.delete(id) : next.add(id);
    setSelectedIds(next);
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === paginated.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(paginated.map(p => p.id)));
    }
  };

  const deleteProduct = (id: string) => {
    DataStore.deleteProduct(id);
    setProducts(DataStore.getProducts());
    refreshData();
    setShowDeleteConfirm(null);
  };

  const bulkDelete = () => {
    selectedIds.forEach(id => DataStore.deleteProduct(id));
    setProducts(DataStore.getProducts());
    refreshData();
    setSelectedIds(new Set());
  };

  const toggleActive = (product: Product) => {
    const updated = { ...product, is_active: !product.is_active };
    DataStore.saveProduct(updated);
    setProducts(DataStore.getProducts());
    refreshData();
  };

  const duplicateProduct = (product: Product) => {
    const newProduct: Product = {
      ...product,
      id: `prod-${Date.now()}`,
      title: `${product.title} (Copy)`,
      slug: `${product.slug}-copy-${Date.now()}`,
      sku: `${product.sku}-COPY`,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };
    DataStore.saveProduct(newProduct);
    setProducts(DataStore.getProducts());
    refreshData();
  };

  const handleCSVExport = () => {
    const headers = ['ID', 'Title', 'Brand', 'Category', 'Base Price', 'Sale Price', 'SKU', 'Stock', 'Active', 'Rating', 'Reviews'];
    const rows = products.map(p => [
      p.id,
      `"${p.title.replace(/"/g, '""')}"`,
      `"${p.brand}"`,
      `"${p.category_name || ''}"`,
      p.base_price,
      p.sale_price || '',
      p.sku,
      p.total_stock,
      p.is_active ? 'Yes' : 'No',
      p.rating_avg,
      p.review_count,
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `ozeira_products_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleCSVImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const text = evt.target?.result as string;
      if (!text) return;

      const lines = text.split('\n').map((l) => l.trim()).filter(Boolean);
      if (lines.length <= 1) return;

      const newItems: Product[] = [];
      for (let i = 1; i < lines.length; i++) {
        const parts = lines[i].split(',').map((s) => s.replace(/^"|"$/g, '').trim());
        if (parts.length >= 7) {
          const title = parts[1] || 'Imported Piece';
          const brand = parts[2] || 'Ozeira';
          const basePrice = parseFloat(parts[4]) || 1999;
          const salePrice = parts[5] ? parseFloat(parts[5]) : undefined;
          const sku = parts[6] || `OZ-IMP-${Date.now()}-${i}`;
          const stock = parseInt(parts[7]) || 10;
          const id = `prod-imp-${Date.now()}-${i}`;
          const slug = title.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '') + `-${Date.now()}`;

          newItems.push({
            id,
            title,
            slug,
            description: title,
            short_description: title,
            brand,
            category_id: categories[0]?.id || 'cat-1',
            category_name: categories[0]?.name || 'Apparel & Knitwear',
            base_price: basePrice,
            sale_price: salePrice,
            discount_percent: salePrice ? Math.round(((basePrice - salePrice) / basePrice) * 100) : 0,
            sku,
            total_stock: stock,
            is_featured: false,
            is_trending: false,
            is_new: true,
            is_active: true,
            rating_avg: 5.0,
            review_count: 0,
            tags: ['imported', 'collection'],
            specifications: {},
            weight_grams: 500,
            images: [
              {
                id: `img-imp-${Date.now()}-${i}`,
                product_id: id,
                image_url: 'https://images.unsplash.com/photo-1548036328-c9fa89d128fa?q=80&w=800',
                sort_order: 1,
                is_primary: true,
              },
            ],
            variants: [
              {
                id: `var-imp-${Date.now()}-${i}`,
                product_id: id,
                sku: `${sku}-STD`,
                additional_price: 0,
                stock_quantity: stock,
              },
            ],
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          });
        }
      }
      if (newItems.length > 0) {
        newItems.forEach((p) => DataStore.saveProduct(p));
        setProducts(DataStore.getProducts());
        refreshData();
        alert(`Successfully imported ${newItems.length} products into catalogue!`);
      }
    };
    reader.readAsText(file);
  };

  if (!mounted) {
    return <div className="animate-pulse space-y-4"><div className="h-10 bg-white dark:bg-[#14151a] rounded-xl" /><div className="h-96 bg-white dark:bg-[#14151a] rounded-xl" /></div>;
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-neutral-900 dark:text-neutral-100">Products Vault</h1>
          <p className="text-sm text-neutral-500 dark:text-neutral-400">{filtered.length} total active catalog pieces</p>
        </div>
        <div className="flex items-center gap-2">
          <label className="px-3 py-2 text-xs font-medium text-neutral-600 dark:text-neutral-400 border border-neutral-200 dark:border-neutral-800 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-800 flex items-center gap-1.5 cursor-pointer transition-colors">
            <Upload className="w-3.5 h-3.5" />
            <span>Import CSV</span>
            <input type="file" accept=".csv" onChange={handleCSVImport} className="hidden" />
          </label>
          <button
            onClick={handleCSVExport}
            className="px-3 py-2 text-xs font-medium text-neutral-600 dark:text-neutral-400 border border-neutral-200 dark:border-neutral-800 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-800 flex items-center gap-1.5 transition-colors"
          >
            <Download className="w-3.5 h-3.5" />
            Export CSV
          </button>
          <button
            onClick={() => setShowAddModal(true)}
            className="px-4 py-2 text-xs font-semibold bg-brand-amber hover:bg-brand-amber-dark text-white rounded-lg flex items-center gap-1.5 transition-colors"
          >
            <Plus className="w-3.5 h-3.5" />
            Add Piece
          </button>
        </div>
      </div>

      {/* Filters bar */}
      <div className="bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 p-4 shadow-sm">
        <div className="flex flex-col lg:flex-row gap-3">
          {/* Search */}
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
            <input
              type="text"
              placeholder="Search products by name, SKU, or brand..."
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setCurrentPage(1); }}
              className="w-full pl-10 pr-4 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg text-xs outline-none focus:border-brand-amber"
            />
          </div>
          {/* Category filter */}
          <select
            value={categoryFilter}
            onChange={(e) => { setCategoryFilter(e.target.value); setCurrentPage(1); }}
            className="px-3 py-2 border border-neutral-200 dark:border-neutral-700 rounded-lg text-xs text-neutral-700 dark:text-neutral-300 bg-white dark:bg-neutral-900 outline-none focus:border-brand-amber"
          >
            <option value="all">All Categories</option>
            {categories.map(c => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>
          {/* Stock filter */}
          <select
            value={stockFilter}
            onChange={(e) => { setStockFilter(e.target.value as StockFilter); setCurrentPage(1); }}
            className="px-3 py-2 border border-neutral-200 dark:border-neutral-700 rounded-lg text-xs text-neutral-700 dark:text-neutral-300 bg-white dark:bg-neutral-900 outline-none focus:border-brand-amber"
          >
            <option value="all">All Stock Status</option>
            <option value="in_stock">In Stock (&gt;5)</option>
            <option value="low_stock">Low Stock (≤5)</option>
            <option value="out_of_stock">Out of Stock</option>
          </select>
        </div>

        {/* Bulk actions */}
        {selectedIds.size > 0 && (
          <div className="mt-3 flex items-center gap-3 p-2 bg-brand-amber/10 rounded-lg border border-brand-amber/20">
            <span className="text-xs font-semibold text-brand-amber">{selectedIds.size} selected</span>
            <button
              onClick={bulkDelete}
              className="text-xs text-red-600 dark:text-red-400 font-medium px-2 py-1 rounded hover:bg-red-50 dark:hover:bg-red-950/40 transition-colors"
            >
              Delete Selected
            </button>
            <button
              onClick={() => setSelectedIds(new Set())}
              className="text-xs text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300 ml-auto"
            >
              Clear Selection
            </button>
          </div>
        )}
      </div>

      {/* Product table */}
      <div className="bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-neutral-100 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900/50">
                <th className="px-4 py-3 text-left">
                  <input
                    type="checkbox"
                    checked={selectedIds.size === paginated.length && paginated.length > 0}
                    onChange={toggleSelectAll}
                    className="w-3.5 h-3.5 rounded text-brand-amber focus:ring-brand-amber accent-brand-amber"
                  />
                </th>
                <th className="px-4 py-3 text-left font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider">Piece</th>
                <th className="px-4 py-3 text-left font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider">SKU</th>
                <th className="px-4 py-3 text-left font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider">Price</th>
                <th className="px-4 py-3 text-left font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider">Stock</th>
                <th className="px-4 py-3 text-left font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider">Status</th>
                <th className="px-4 py-3 text-left font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider">Rating</th>
                <th className="px-4 py-3 text-right font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-neutral-100 dark:divide-neutral-800">
              {paginated.map((product) => {
                const primaryImage = product.images?.find(i => i.is_primary)?.image_url || product.images?.[0]?.image_url;
                return (
                  <tr key={product.id} className={cn('hover:bg-neutral-50/50 dark:hover:bg-neutral-900/50 transition-colors', selectedIds.has(product.id) && 'bg-brand-amber/5 dark:bg-brand-amber/10')}>
                    <td className="px-4 py-3">
                      <input
                        type="checkbox"
                        checked={selectedIds.has(product.id)}
                        onChange={() => toggleSelect(product.id)}
                        className="w-3.5 h-3.5 rounded text-brand-amber focus:ring-brand-amber accent-brand-amber"
                      />
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-lg bg-neutral-100 dark:bg-neutral-800 overflow-hidden flex-shrink-0 border border-neutral-200 dark:border-neutral-700">
                          {primaryImage ? (
                            <img src={primaryImage} alt={product.title} className="w-full h-full object-cover" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center">
                              <ImageIcon className="w-4 h-4 text-neutral-400" />
                            </div>
                          )}
                        </div>
                        <div className="min-w-0">
                          <p className="font-semibold text-neutral-900 dark:text-neutral-100 truncate max-w-[220px]">{product.title}</p>
                          <p className="text-[11px] text-neutral-400">{product.category_name || 'Uncategorized'}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-3">
                      <span className="font-mono text-neutral-600 dark:text-neutral-400">{product.sku}</span>
                    </td>
                    <td className="px-4 py-3">
                      <div>
                        <span className="font-bold text-neutral-900 dark:text-neutral-100">
                          {formatPriceValue(product.sale_price || product.base_price)}
                        </span>
                        {product.sale_price && (
                          <span className="text-[10px] text-neutral-400 line-through ml-1.5">
                            {formatPriceValue(product.base_price)}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-4 py-3">
                      <span className={cn(
                        'font-semibold',
                        product.total_stock === 0 && 'text-red-600 dark:text-red-400',
                        product.total_stock > 0 && product.total_stock <= 5 && 'text-amber-600 dark:text-amber-400',
                        product.total_stock > 5 && 'text-emerald-600 dark:text-emerald-400',
                      )}>
                        {product.total_stock}
                        {product.total_stock === 0 && (
                          <AlertTriangle className="w-3 h-3 inline-block ml-1" />
                        )}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <button
                        onClick={() => toggleActive(product)}
                        className={cn(
                          'text-[10px] font-semibold px-2 py-0.5 rounded-full border',
                          product.is_active
                            ? 'text-emerald-700 dark:text-emerald-300 bg-emerald-50 dark:bg-emerald-950/40 border-emerald-200 dark:border-emerald-900/50'
                            : 'text-neutral-500 bg-neutral-50 dark:bg-neutral-800 border-neutral-200 dark:border-neutral-700'
                        )}
                      >
                        {product.is_active ? 'Active' : 'Inactive'}
                      </button>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-1">
                        <Star className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
                        <span className="text-neutral-800 dark:text-neutral-200 font-medium">{product.rating_avg.toFixed(1)}</span>
                        <span className="text-neutral-400">({product.review_count})</span>
                      </div>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center justify-end gap-1">
                        <Link
                          href={`/product/${product.slug}`}
                          target="_blank"
                          className="p-1.5 text-neutral-400 hover:text-brand-amber hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
                          title="View on storefront"
                        >
                          <Eye className="w-3.5 h-3.5" />
                        </Link>
                        <button
                          onClick={() => setEditingProduct(product)}
                          className="p-1.5 text-neutral-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-950/30 rounded-lg transition-colors"
                          title="Edit"
                        >
                          <Edit2 className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={() => duplicateProduct(product)}
                          className="p-1.5 text-neutral-400 hover:text-purple-500 hover:bg-purple-50 dark:hover:bg-purple-950/30 rounded-lg transition-colors"
                          title="Duplicate"
                        >
                          <Copy className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={() => setShowDeleteConfirm(product.id)}
                          className="p-1.5 text-neutral-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-950/30 rounded-lg transition-colors"
                          title="Delete"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {paginated.length === 0 && (
                <tr>
                  <td colSpan={8} className="px-4 py-12 text-center">
                    <Package className="w-10 h-10 text-neutral-300 dark:text-neutral-700 mx-auto mb-2" />
                    <p className="text-sm text-neutral-500 dark:text-neutral-400">No products found</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between px-4 py-3 border-t border-neutral-100 dark:border-neutral-800 text-xs">
            <p className="text-neutral-500 dark:text-neutral-400">
              Showing {(currentPage - 1) * itemsPerPage + 1} to {Math.min(currentPage * itemsPerPage, filtered.length)} of {filtered.length} pieces
            </p>
            <div className="flex items-center gap-1">
              <button
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-1.5 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 disabled:opacity-30 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                <button
                  key={page}
                  onClick={() => setCurrentPage(page)}
                  className={cn(
                    'w-7 h-7 rounded-lg font-medium transition-colors',
                    page === currentPage
                      ? 'bg-brand-amber text-white'
                      : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800'
                  )}
                >
                  {page}
                </button>
              ))}
              <button
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="p-1.5 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 disabled:opacity-30 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Delete confirmation modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => setShowDeleteConfirm(null)}>
          <div className="bg-white dark:bg-[#14151a] text-neutral-900 dark:text-neutral-100 rounded-2xl border border-neutral-200 dark:border-neutral-800 max-w-sm w-full p-6 shadow-2xl" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-12 bg-red-100 dark:bg-red-950/40 rounded-full flex items-center justify-center mx-auto mb-4">
              <Trash2 className="w-6 h-6 text-red-600 dark:text-red-400" />
            </div>
            <h3 className="text-base font-bold text-center">Archive Piece Permanently?</h3>
            <p className="text-xs text-neutral-500 dark:text-neutral-400 text-center mt-2">This will remove the product and all associated variants from live display.</p>
            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setShowDeleteConfirm(null)}
                className="flex-1 px-4 py-2 border border-neutral-200 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300 rounded-xl text-xs font-semibold hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => deleteProduct(showDeleteConfirm)}
                className="flex-1 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-xl text-xs font-semibold transition-colors"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit Product Modal */}
      {(showAddModal || editingProduct) && (
        <ProductFormModal
          product={editingProduct}
          categories={categories}
          onClose={() => { setShowAddModal(false); setEditingProduct(null); }}
          onSave={(product) => {
            DataStore.saveProduct(product);
            setProducts(DataStore.getProducts());
            refreshData();
            setShowAddModal(false);
            setEditingProduct(null);
          }}
        />
      )}
    </div>
  );
}

// ========== Product Form Modal ==========
function ProductFormModal({
  product,
  categories,
  onClose,
  onSave,
}: {
  product: Product | null;
  categories: Category[];
  onClose: () => void;
  onSave: (product: Product) => void;
}) {
  const isEditing = !!product;
  const [form, setForm] = useState({
    title: product?.title || '',
    description: product?.description || '',
    short_description: product?.short_description || '',
    brand: product?.brand || 'Ozeira',
    category_id: product?.category_id || '',
    base_price: product?.base_price?.toString() || '',
    sale_price: product?.sale_price?.toString() || '',
    discount_percent: product?.discount_percent?.toString() || '0',
    sku: product?.sku || '',
    total_stock: product?.total_stock?.toString() || '0',
    weight_grams: product?.weight_grams?.toString() || '0',
    dimensions: product?.dimensions || '',
    is_featured: product?.is_featured || false,
    is_trending: product?.is_trending || false,
    is_new: product?.is_new || true,
    is_active: product?.is_active ?? true,
    meta_title: product?.meta_title || '',
    meta_description: product?.meta_description || '',
    tags: product?.tags?.join(', ') || '',
    image_url: product?.images?.[0]?.image_url || '',
  });

  const [activeTab, setActiveTab] = useState<'basic' | 'pricing' | 'media' | 'seo'>('basic');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const slug = form.title.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
    const now = new Date().toISOString();
    const category = categories.find(c => c.id === form.category_id);

    const productData: Product = {
      id: product?.id || `prod-${Date.now()}`,
      title: form.title,
      slug: product?.slug || slug,
      description: form.description,
      short_description: form.short_description,
      category_id: form.category_id,
      category_name: category?.name,
      brand: form.brand,
      base_price: parseFloat(form.base_price) || 0,
      sale_price: form.sale_price ? parseFloat(form.sale_price) : undefined,
      discount_percent: parseFloat(form.discount_percent) || 0,
      sku: form.sku || `OZ-${Date.now()}`,
      total_stock: parseInt(form.total_stock) || 0,
      is_featured: form.is_featured,
      is_trending: form.is_trending,
      is_new: form.is_new,
      rating_avg: product?.rating_avg || 0,
      review_count: product?.review_count || 0,
      tags: form.tags.split(',').map(t => t.trim()).filter(Boolean),
      specifications: product?.specifications || {},
      weight_grams: parseInt(form.weight_grams) || 0,
      dimensions: form.dimensions,
      is_active: form.is_active,
      meta_title: form.meta_title,
      meta_description: form.meta_description,
      images: form.image_url
        ? [{ id: product?.images?.[0]?.id || `img-${Date.now()}`, product_id: product?.id || '', image_url: form.image_url, alt_text: form.title, sort_order: 0, is_primary: true }]
        : product?.images || [],
      variants: product?.variants || [],
      created_at: product?.created_at || now,
      updated_at: now,
    };
    onSave(productData);
  };

  const tabs = [
    { id: 'basic', label: 'Basic Info' },
    { id: 'pricing', label: 'Pricing & Stock' },
    { id: 'media', label: 'Media' },
    { id: 'seo', label: 'SEO' },
  ] as const;

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-start justify-center p-4 overflow-y-auto" onClick={onClose}>
      <div className="bg-white dark:bg-[#14151a] text-neutral-900 dark:text-neutral-100 rounded-2xl border border-neutral-200 dark:border-neutral-800 max-w-2xl w-full my-8 shadow-2xl overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between p-5 border-b border-neutral-200 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900/50">
          <h2 className="text-base font-bold text-neutral-900 dark:text-neutral-100">{isEditing ? 'Edit Catalog Piece' : 'Add New Atelier Piece'}</h2>
          <button onClick={onClose} className="p-1.5 text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-200 rounded-lg">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-neutral-200 dark:border-neutral-800 px-5">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={cn(
                'px-4 py-3 text-xs font-semibold border-b-2 -mb-px transition-colors',
                activeTab === tab.id
                  ? 'border-brand-amber text-brand-amber font-bold'
                  : 'border-transparent text-neutral-500 dark:text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-200'
              )}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <form onSubmit={handleSubmit} className="p-5 space-y-4 text-xs">
          {activeTab === 'basic' && (
            <>
              <div>
                <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Product Title *</label>
                <input
                  type="text"
                  required
                  value={form.title}
                  onChange={e => setForm(f => ({ ...f, title: e.target.value }))}
                  className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  placeholder="e.g. Celestial Silk Drape Blouse"
                />
              </div>
              <div>
                <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Short Description</label>
                <input
                  type="text"
                  value={form.short_description}
                  onChange={e => setForm(f => ({ ...f, short_description: e.target.value }))}
                  className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  placeholder="Brief product tagline"
                />
              </div>
              <div>
                <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Full Description</label>
                <textarea
                  rows={4}
                  value={form.description}
                  onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                  className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber resize-none"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Brand</label>
                  <input
                    type="text"
                    value={form.brand}
                    onChange={e => setForm(f => ({ ...f, brand: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  />
                </div>
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Category</label>
                  <select
                    value={form.category_id}
                    onChange={e => setForm(f => ({ ...f, category_id: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  >
                    <option value="">Select category</option>
                    {categories.map(c => (
                      <option key={c.id} value={c.id}>{c.name}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div>
                <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Tags (comma separated)</label>
                <input
                  type="text"
                  value={form.tags}
                  onChange={e => setForm(f => ({ ...f, tags: e.target.value }))}
                  className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  placeholder="luxury, silk, premium"
                />
              </div>
              <div className="flex flex-wrap gap-4 pt-1">
                {(['is_featured', 'is_trending', 'is_new', 'is_active'] as const).map(key => (
                  <label key={key} className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={form[key]}
                      onChange={e => setForm(f => ({ ...f, [key]: e.target.checked }))}
                      className="w-3.5 h-3.5 rounded text-brand-amber focus:ring-brand-amber accent-brand-amber"
                    />
                    <span className="text-xs text-neutral-700 dark:text-neutral-300 capitalize">{key.replace('is_', '').replace('_', ' ')}</span>
                  </label>
                ))}
              </div>
            </>
          )}

          {activeTab === 'pricing' && (
            <>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Base Price (₹) *</label>
                  <input
                    type="number"
                    required
                    min="0"
                    value={form.base_price}
                    onChange={e => setForm(f => ({ ...f, base_price: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  />
                </div>
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Sale Price (₹)</label>
                  <input
                    type="number"
                    min="0"
                    value={form.sale_price}
                    onChange={e => setForm(f => ({ ...f, sale_price: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  />
                </div>
              </div>
              <div className="grid grid-cols-3 gap-4">
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">SKU</label>
                  <input
                    type="text"
                    value={form.sku}
                    onChange={e => setForm(f => ({ ...f, sku: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg font-mono outline-none focus:border-brand-amber"
                  />
                </div>
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Total Stock</label>
                  <input
                    type="number"
                    min="0"
                    value={form.total_stock}
                    onChange={e => setForm(f => ({ ...f, total_stock: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  />
                </div>
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Discount %</label>
                  <input
                    type="number"
                    min="0"
                    max="100"
                    value={form.discount_percent}
                    onChange={e => setForm(f => ({ ...f, discount_percent: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Weight (grams)</label>
                  <input
                    type="number"
                    min="0"
                    value={form.weight_grams}
                    onChange={e => setForm(f => ({ ...f, weight_grams: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  />
                </div>
                <div>
                  <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Dimensions</label>
                  <input
                    type="text"
                    value={form.dimensions}
                    onChange={e => setForm(f => ({ ...f, dimensions: e.target.value }))}
                    className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                    placeholder="e.g. 30 × 25 × 5 cm"
                  />
                </div>
              </div>
            </>
          )}

          {activeTab === 'media' && (
            <div className="space-y-4">
              <div>
                <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Product Media (Supabase Bucket: ozeira-products)</label>
                <p className="text-[11px] text-neutral-500 dark:text-neutral-400 mb-3">
                  Upload high-resolution photography. Images are automatically optimized and cached on Supabase CDN for instant worldwide delivery.
                </p>
                <ImageUploadDropzone
                  bucket="ozeira-products"
                  folder="catalog"
                  currentImageUrl={form.image_url}
                  onImageUploaded={(url) => setForm(f => ({ ...f, image_url: url }))}
                  onImageRemoved={() => setForm(f => ({ ...f, image_url: '' }))}
                  aspectRatio="square"
                  label="Primary Product Image"
                />
              </div>

              <div>
                <label className="block text-[11px] font-semibold text-neutral-600 dark:text-neutral-400 uppercase tracking-wider mb-1">Or Provide Image URL directly</label>
                <input
                  type="url"
                  value={form.image_url}
                  onChange={e => setForm(f => ({ ...f, image_url: e.target.value }))}
                  className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg font-mono text-xs outline-none focus:border-brand-amber"
                  placeholder="https://rgqzcjrduahsdkmqfuvr.supabase.co/storage/v1/object/public/..."
                />
              </div>
            </div>
          )}

          {activeTab === 'seo' && (
            <>
              <div>
                <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Meta Title</label>
                <input
                  type="text"
                  value={form.meta_title}
                  onChange={e => setForm(f => ({ ...f, meta_title: e.target.value }))}
                  className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber"
                  placeholder="SEO page title"
                />
              </div>
              <div>
                <label className="block font-semibold text-neutral-700 dark:text-neutral-300 mb-1">Meta Description</label>
                <textarea
                  rows={3}
                  value={form.meta_description}
                  onChange={e => setForm(f => ({ ...f, meta_description: e.target.value }))}
                  className="w-full px-3 py-2 border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 rounded-lg outline-none focus:border-brand-amber resize-none"
                  placeholder="SEO description for search engines"
                />
              </div>
            </>
          )}

          <div className="flex justify-end gap-3 pt-4 border-t border-neutral-200 dark:border-neutral-800">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 border border-neutral-200 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300 rounded-lg font-medium hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-6 py-2 bg-brand-amber hover:bg-brand-amber-dark text-white rounded-lg font-semibold transition-colors"
            >
              {isEditing ? 'Update Piece' : 'Add Piece'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { DataStore } from '@/lib/store/data-store';
import { formatDateTime, cn } from '@/lib/utils';
import { Users, UserPlus, ShieldAlert, CheckCircle2 } from 'lucide-react';
import type { Referral, UserProfile } from '@/types';

export default function ReferralsAdminPage() {
  const [referrals, setReferrals] = useState<Referral[]>([]);
  const [users, setUsers] = useState<UserProfile[]>([]);

  useEffect(() => {
    setReferrals(DataStore.getReferrals());
    setUsers(DataStore.getUsers());
  }, []);

  const totalRef = referrals.length;
  const rewardedRef = referrals.filter(r => r.status === 'rewarded').length;
  const pendingRef = referrals.filter(r => r.status === 'signed_up' || r.status === 'first_order_placed').length;
  const flaggedRef = referrals.filter(r => r.status === 'flagged').length;

  const toggleFlag = (ref: Referral) => {
    const updated = referrals.map(r => {
      if (r.id === ref.id) {
        return { ...r, status: r.status === 'flagged' ? 'signed_up' : 'flagged' } as Referral;
      }
      return r;
    });
    localStorage.setItem('ozeira_referrals_v1', JSON.stringify(updated));
    setReferrals(updated);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight text-neutral-900 dark:text-neutral-100">Patron Invitations & Referrals</h1>
        <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-1">Audit invitation chains, conversion milestones, and reward fulfillment.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <div className="flex items-center gap-3"><Users className="w-5 h-5 text-neutral-400" /><p className="text-neutral-500 dark:text-neutral-400 text-xs font-medium">Total Referrals</p></div>
          <p className="text-2xl font-bold mt-2 text-neutral-900 dark:text-neutral-100">{totalRef}</p>
        </div>
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <div className="flex items-center gap-3"><CheckCircle2 className="w-5 h-5 text-emerald-500" /><p className="text-neutral-500 dark:text-neutral-400 text-xs font-medium">Rewarded</p></div>
          <p className="text-2xl font-bold mt-2 text-neutral-900 dark:text-neutral-100">{rewardedRef}</p>
        </div>
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <div className="flex items-center gap-3"><UserPlus className="w-5 h-5 text-blue-500" /><p className="text-neutral-500 dark:text-neutral-400 text-xs font-medium">Pending</p></div>
          <p className="text-2xl font-bold mt-2 text-neutral-900 dark:text-neutral-100">{pendingRef}</p>
        </div>
        <div className="bg-white dark:bg-[#14151a] p-5 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
          <div className="flex items-center gap-3"><ShieldAlert className="w-5 h-5 text-red-500" /><p className="text-neutral-500 dark:text-neutral-400 text-xs font-medium">Flagged</p></div>
          <p className="text-2xl font-bold mt-2 text-neutral-900 dark:text-neutral-100">{flaggedRef}</p>
        </div>
      </div>

      <div className="bg-white dark:bg-[#14151a] p-6 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
        <h2 className="text-base font-bold text-neutral-900 dark:text-neutral-100 mb-4">Referral Activity Log</h2>
        <div className="overflow-x-auto">
          <table className="w-full text-xs text-left">
            <thead className="bg-neutral-50 dark:bg-neutral-900 text-neutral-500 dark:text-neutral-400 font-semibold uppercase tracking-wider">
              <tr>
                <th className="py-3 px-4">Date</th>
                <th className="py-3 px-4">Referrer</th>
                <th className="py-3 px-4">Referee</th>
                <th className="py-3 px-4">Status</th>
                <th className="py-3 px-4">Reward</th>
                <th className="py-3 px-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-neutral-100 dark:divide-neutral-800">
              {referrals.map(r => {
                const referrer = users.find(u => u.id === r.referrer_id);
                return (
                  <tr key={r.id} className="hover:bg-neutral-50 dark:hover:bg-neutral-900/50 transition-colors">
                    <td className="py-3 px-4 whitespace-nowrap text-neutral-500 dark:text-neutral-400">{formatDateTime(r.created_at)}</td>
                    <td className="py-3 px-4 font-semibold text-neutral-900 dark:text-neutral-100">{r.referrer_name || referrer?.full_name || 'Atelier Patron'}</td>
                    <td className="py-3 px-4">
                      <span className="font-medium text-neutral-900 dark:text-neutral-100">{r.referee_name}</span>
                      <br /><span className="text-[11px] text-neutral-400 font-mono">{r.referee_email}</span>
                    </td>
                    <td className="py-3 px-4">
                      <span className={cn(
                        "px-2 py-0.5 rounded-full text-[11px] font-semibold uppercase tracking-wider",
                        r.status === 'rewarded' && "bg-emerald-100 text-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300",
                        (r.status === 'signed_up' || r.status === 'first_order_placed') && "bg-blue-100 text-blue-800 dark:bg-blue-950/40 dark:text-blue-300",
                        r.status === 'flagged' && "bg-red-100 text-red-800 dark:bg-red-950/40 dark:text-red-300"
                      )}>
                        {r.status.replace(/_/g, ' ')}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-brand-amber font-bold">{r.reward_points} pts</td>
                    <td className="py-3 px-4 text-right">
                      <button onClick={() => toggleFlag(r)} className="text-xs text-neutral-500 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-neutral-100 border border-neutral-200 dark:border-neutral-700 rounded-lg px-2.5 py-1 transition-colors">
                        {r.status === 'flagged' ? 'Unflag' : 'Flag'}
                      </button>
                    </td>
                  </tr>
                );
              })}
              {referrals.length === 0 && (
                <tr>
                  <td colSpan={6} className="text-center py-8 text-neutral-500 dark:text-neutral-400">No referrals found in ledger.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
